"""Build an additive grammar reader; never modifies account material records."""
import json, hashlib, re
from pathlib import Path
book=json.loads(Path('public/data/grammar-book-a1-b2.json').read_text())['items']
rows={}
def unit(names,guide,rule,de,vi,trap,question,answer,bad1,why1,bad2,why2):
 for title in names.split('|'):
  assert title not in rows,title
  rows[title]=dict(guide=guide,rule=rule,de=de,vi=vi,trap=trap,question=question,answer=answer,bad1=bad1,why1=why1,bad2=bad2,why2=why2)
# Guide indexes point at reviewed, previously authored explanations, not third-party text.
unit('Adjektive',13,'Tính từ mô tả đặc tính. Sau sein/werden/bleiben, tính từ vị ngữ không thêm đuôi; trước danh từ, nó phải biến cách. Phân biệt chức năng trước khi học bảng đuôi.','Das Zimmer ist ruhig.','Căn phòng yên tĩnh.','Không viết Das Zimmer ist ruhiges; -es chỉ có thể thuộc mẫu định ngữ như ein ruhiges Zimmer.','Das Zimmer ist ___. (ruhig)','ruhig','ruhiges','Sau ist, tính từ vị ngữ không nhận đuôi.','ruhigen','-en không thuộc tính từ vị ngữ ở đây.')
unit('Adjektive im Komparativ',14,'So sánh hơn thường thêm -er; một số tính từ có Umlaut hoặc dạng bất quy tắc. Khi có đối tượng so sánh khác mức độ, dùng als. Komparativ đứng trước danh từ vẫn phải thêm đuôi biến cách sau -er.','Dieser Weg ist kürzer als der andere.','Con đường này ngắn hơn con đường kia.','Kürzer als, không phải kürzer wie trong văn viết chuẩn. Ein kürzerer Weg có cả -er so sánh và -er biến cách.','Dieser Weg ist ___ als jener. (kurz)','kürzer','kurzer','Kurz có Umlaut trong Komparativ.','am kürzesten','Am kürzesten là Superlativ, không dùng với als như câu này.')
unit('Adjektive im Superlativ',14,'So sánh nhất: am + -(e)sten khi dùng vị ngữ/trạng ngữ; trước danh từ dùng mạo từ và dạng -(e)st- có đuôi. Với âm cuối khó đọc thường có e: heiß → am heißesten.','Dieser Weg ist am kürzesten.','Con đường này ngắn nhất.','Der kürzeste Weg nhưng dieser Weg ist am kürzesten. Không ghép am với der trước cùng tính từ.','Sie läuft ___. (schnell; so sánh nhất)','am schnellsten','schneller','Schneller là so sánh hơn, chưa phải nhất.','am schnellster','Sau am, mẫu trạng ngữ dùng -sten.')
unit('Akkusativ|im Akkusativ',3,'Akkusativ thường đánh dấu tân ngữ trực tiếp, hoặc được giới từ/động từ yêu cầu. Giống đực: der/ein → den/einen; giống cái die/eine, trung das/ein, số nhiều die không đổi mạo từ xác định. Hỏi wen/was khi đó là tân ngữ.','Ich sehe einen Mann.','Tôi nhìn thấy một người đàn ông.','Không quyết định cách chỉ bằng dịch tiếng Việt. Sehen + Akkusativ; für cũng luôn yêu cầu Akkusativ trong mẫu giới từ.','Ich sehe ___ Mann. (ein)','einen','einem','Einem là Dativ; sehen ở đây cần Akkusativ.','eines','Eines là Genitiv, không phải tân ngữ của sehen.')
unit('Dativ|im Dativ',3,'Dativ là bổ ngữ do động từ hoặc giới từ yêu cầu, thường chỉ người nhận: dem Mann, der Frau, dem Kind, den Kindern. Danh từ số nhiều thường thêm -n nếu dạng số nhiều chưa có -n/-s. Đại từ ich → mir, du → dir.','Ich helfe dem Kind.','Tôi giúp đứa trẻ.','Helfen luôn đi với Dativ trong nghĩa giúp ai. Không đổi thành Akkusativ theo thói quen tiếng Việt.','Ich helfe ___ Kind. (das)','dem','das','Das là Nominativ/Akkusativ, không đáp ứng helfen + Dativ.','den','Den không phải mạo từ Dativ trung số ít.')
unit('Nominativ',3,'Nominativ thường là chủ ngữ, chi phối việc chia động từ. Sau sein/werden/bleiben, cụm danh từ vị ngữ thường cũng ở Nominativ. Vị trí đầu câu không đảm bảo là chủ ngữ: Heute sieht der Mann den Hund.','Der Mann ist Lehrer.','Người đàn ông là giáo viên.','Đừng gọi mọi cụm đầu câu là Nominativ. Trong Den Mann sehe ich, den Mann là Akkusativ còn ich mới là chủ ngữ.','___ Mann kommt heute. (der)','Der','Den','Den là Akkusativ; người thực hiện kommt là chủ ngữ.','Dem','Dem là Dativ, không làm chủ ngữ này.')
unit('Dativ Akkusativ Übungen',3,'Luyện theo hai bước: tìm động từ/giới từ chi phối, rồi xác định giống và số. Cặp schenken: người nhận Dativ, vật được tặng Akkusativ. Không chọn cách theo vị trí đứng trước hay sau động từ.','Ich schenke dem Kind einen Ball.','Tôi tặng đứa trẻ một quả bóng.','Dem Kind là người nhận; einen Ball là vật. Đổi trật tự không làm đổi vai trò và cách.','Ich schenke ___ Kind einen Ball. (das)','dem','das','Người nhận của schenken cần Dativ.','des','Des là Genitiv, không chỉ người nhận ở đây.')
unit('Dativ oder Akkusativ',35,'Với Wechselpräpositionen, phân biệt vị trí (wo, Dativ) và đích thay đổi vị trí (wohin, Akkusativ). Ngoài nhóm này, học rektion riêng: mit + Dativ, für + Akkusativ, helfen + Dativ. Không dùng quy tắc chuyển động cho tất cả giới từ.','Ich lege das Buch auf den Tisch.','Tôi đặt quyển sách lên bàn.','Auf dem Tisch laufen vẫn Dativ nếu chạy ở trên bàn, không chuyển đến một đích mới.','Das Buch liegt auf ___ Tisch. (der)','dem','den','Den chỉ đích với legen; liegt mô tả vị trí.','des','Auf không đòi Genitiv trong mẫu này.')
unit('Artikel|Bestimmter Artikel: der, die, das',1,'Học danh từ cùng giống và số nhiều. Der/die/das dùng khi đối tượng xác định trong ngữ cảnh, đã được nhắc đến hoặc có thể nhận diện. Giống ngữ pháp không luôn trùng giới tính; das Mädchen là giống trung. Mạo từ còn biến đổi theo cách.','Das Mädchen liest ein Buch.','Cô bé đang đọc một quyển sách.','Không viết die Mädchen khi muốn một cô bé ở số ít; die Mädchen là số nhiều.','___ Mädchen liest. (mạo từ xác định, số ít)','Das','Die','Mädchen số ít giống trung; die chỉ dùng cho số nhiều ở đây.','Der','Der không phải Nominativ trung.')
unit('Unbestimmter Artikel: ein, eine, einen',1,'Ein/eine giới thiệu một đối tượng chưa xác định, số ít. Không có dạng số nhiều của ein; Bücher có thể dùng không mạo từ. Giống đực chỉ biến ein thành einen ở Akkusativ; Dativ là einem/einer/einem.','Ich kaufe einen Apfel.','Tôi mua một quả táo.','Ein Apfel làm chủ ngữ nhưng einen Apfel làm tân ngữ kaufen. Không áp einen cho mọi giống.','Ich kaufe ___ Apfel. (ein)','einen','ein','Apfel giống đực, tân ngữ Akkusativ cần einen.','eine','Eine dùng giống cái, không phải der Apfel.')
unit('Demonstrativpronomen',10,'Dieser/diese/dieses chỉ đối tượng cụ thể hoặc đối chiếu. Nó biến cách theo giống, số, cách của đối tượng, có thể đứng trước danh từ hoặc độc lập. Dieser hier ist besser: đại từ thay cho một danh từ đã rõ.','Dieses Buch gehört mir.','Quyển sách này thuộc về tôi.','Nicht jeder dieser đều có nghĩa khoảng cách gần vật lý; nó còn chỉ cái vừa đề cập trong văn bản.','___ Buch gehört mir. (dies-)','Dieses','Dieser','Buch giống trung, Nominativ cần dieses.','Diesen','Diesen là Akkusativ đực hoặc Dativ số nhiều, không phù hợp.')
unit('Possessivartikel',10,'Mein/dein/sein/ihr/unser/euer/Ihr đứng trước danh từ. Gốc cho biết chủ sở hữu, đuôi phụ thuộc vật sở hữu và cách. Sein Buch có thể là sách của một người nam; ihr Buch có thể là sách của một người nữ hoặc nhiều người.','Ich suche meinen Schlüssel.','Tôi đang tìm chìa khóa của mình.','Chọn mein theo người sở hữu ich nhưng -en theo Schlüssel giống đực Akkusativ. Không chọn đuôi theo giới tính người sở hữu.','Ich suche ___ Schlüssel. (mein)','meinen','mein','Schlüssel là tân ngữ giống đực, cần -en.','meiner','Meiner không phải Akkusativ đực trước danh từ này.')
unit('Possessivpronomen',22,'Đại từ sở hữu đứng độc lập thay cả cụm danh từ. Phân biệt mein Buch với Das ist meins/meines. Dạng đại từ phải mang tín hiệu giống/cách mà danh từ bị lược bỏ không còn thể hiện.','Ist das dein Stift? Ja, das ist meiner.','Đó là bút của bạn à? Vâng, là của tôi.','Mein không có đuôi trước Stift ở Nominativ, nhưng đứng độc lập cần meiner.','Dieser Stift ist ___. (mein; đại từ độc lập)','meiner','mein','Mein là dạng từ hạn định trước danh từ, không phải dạng độc lập cần ở đây.','meines','Meines thay một danh từ trung, không phải der Stift.')
unit('Personalpronomen',11,'Đại từ nhân xưng thay người/vật và biến cách: ich/mich/mir; du/dich/dir; er/ihn/ihm; sie/sie/ihr; wir/uns/uns. Sie viết hoa chỉ xưng hô lịch sự; động từ dùng dạng như ngôi số nhiều.','Sie gibt mir das Buch.','Cô ấy đưa quyển sách cho tôi.','Mir không đồng nghĩa mich: geben chỉ người nhận bằng Dativ. Nhìn động từ và vai trò trước khi chọn dạng.','Sie gibt ___ das Buch. (ich)','mir','mich','Mich là Akkusativ, không phải người nhận Dativ ở đây.','ich','Ich là Nominativ, không dùng làm bổ ngữ này.')
unit('Mir oder mich',11,'Mir là Dativ, mich là Akkusativ của ich. Dùng helfen/danken/gefallen + mir, sehen/anrufen/besuchen + mich. Khi phản thân, rửa tay: Ich wasche mir die Hände, vì die Hände đã là Akkusativ.','Kannst du mir helfen?','Bạn có thể giúp tôi không?','Nicht: Kannst du mich helfen? Đây là lỗi rektion, không phải lỗi thứ tự từ.','Kannst du ___ anrufen? (ich)','mich','mir','Anrufen cần người được gọi ở Akkusativ.','ich','Ich là chủ ngữ; câu này chủ ngữ đã là du.')
unit('Fragesatz|W-Fragen',2,'Câu hỏi có W-Wort đặt từ/cụm hỏi đầu rồi động từ đã chia: Wo wohnst du? Câu hỏi có/không bắt đầu bằng động từ: Wohnst du hier? Cụm hỏi có thể dài: Mit welchem Bus fährst du?','Wann kommst du?','Khi nào bạn đến?','Không dùng trật tự câu trần thuật Wo du wohnst? trong câu hỏi trực tiếp chuẩn. Trật tự đó thuộc câu hỏi gián tiếp.','Wo ___ du? (wohnen)','wohnst','du wohnst','Chủ ngữ du đã có sau chỗ trống; cần động từ ở V2.','wohnen','Du cần -st, không phải nguyên mẫu.')
unit('Fragewörter welcher, welche, welches',10,'Welcher hỏi chọn một trong nhóm đã rõ. Đuôi theo danh từ: welcher Bus, welche Straße, welches Hotel; Akkusativ đực welchen Bus; Dativ mit welchem Bus. Khác was für ein hỏi loại/tính chất.','Mit welchem Bus fährst du?','Bạn đi bằng xe buýt nào?','Mit yêu cầu Dativ; không viết mit welchen Bus ở số ít.','___ Bus nimmst du? (welch-)','Welchen','Welcher','Bus là tân ngữ Akkusativ, không phải chủ ngữ.','Welchem','Welchem là Dativ; nehmen ở đây cần Akkusativ.')
unit('Fragewort was für ein',10,'Was für ein/eine hỏi loại hoặc tính chất, không phải chọn thành viên cụ thể trong một danh sách. Ein biến cách theo danh từ và cấu trúc câu: Was für einen Film siehst du? Für trong cụm hỏi này không tự chi phối Akkusativ.','Was für ein Auto fährst du?','Bạn lái loại xe gì?','Mit was für einem Auto: einem do mit yêu cầu Dativ. Không áp für + Akkusativ lên cả cụm nghi vấn.','Mit was für ___ Auto fährst du? (ein)','einem','einen','Auto trung và sau mit là Dativ: einem.','ein','Dativ cần einem, không dùng dạng không đuôi.')
unit('Interrogativpronomen',2,'Wer hỏi chủ ngữ người, wen hỏi Akkusativ, wem hỏi Dativ, wessen hỏi sở hữu. Was hỏi sự vật/sự việc. Cách của đại từ phụ thuộc vị trí bị hỏi trong câu trả lời, không phụ thuộc cách của người đặt câu hỏi.','Wem gehört das Fahrrad?','Chiếc xe đạp thuộc về ai?','Gehören + Dativ nên hỏi wem, không phải wen. Wessen Fahrrad là một cấu trúc sở hữu khác.','___ hilfst du? (hỏi người)','Wem','Wen','Helfen dùng Dativ, wen là Akkusativ.','Wer','Wer là Nominativ, không phải bổ ngữ của helfen.')
unit('Nomen|Plural',1,'Danh từ viết hoa. Số nhiều có các mẫu -e, -er, -(e)n, -s hoặc không đổi; có thể đổi Umlaut. Không suy một quy tắc duy nhất cho mọi từ. Mạo từ Nominativ/Akkusativ số nhiều là die; Dativ thường thêm -n cho danh từ nếu cần.','Die Kinder spielen im Garten.','Bọn trẻ đang chơi trong vườn.','Das Kind → die Kinder, không phải Kinds. Luôn học cùng danh từ gốc, giống và số nhiều.','Số nhiều của das Kind: die ___.','Kinder','Kinds','-s không phải đuôi số nhiều của Kind.','Kindern','Kindern là Dativ số nhiều, câu hỏi cần dạng từ điển Nominativ.')
unit('Komposita',50,'Danh từ ghép nhận giống từ thành phần cuối: die Tür + der Schlüssel → der Türschlüssel. Thành phần trước thu hẹp nghĩa. Có thể có âm nối -s-, -n-; không tùy ý thêm hoặc bỏ vì không phải lúc nào cũng đoán được.','Der Wohnungsschlüssel liegt hier.','Chìa khóa căn hộ nằm ở đây.','Die Wohnung nhưng der Wohnungsschlüssel vì từ cuối là der Schlüssel. Viết hoa đầu cả từ ghép, không tách các danh từ một cách tùy tiện.','___ Haustür ist offen. (mạo từ xác định)','Die','Das','Haus không quyết định giống; từ cuối Tür giống cái.','Der','Tür là giống cái, Nominativ cần die.')
unit('Genitiv|im Genitiv',24,'Genitiv biểu thị sở hữu/quan hệ hoặc do động từ/giới từ đòi hỏi. Giống đực/trung thường dùng des và danh từ thêm -(e)s; giống cái/số nhiều dùng der. Không phải mọi quan hệ sở hữu đều bắt buộc Genitiv trong mọi văn phong.','Das ist die Tasche des Lehrers.','Đó là túi của thầy giáo.','Des Lehrer thiếu -s ở danh từ; riêng danh từ yếu như der Student dùng des Studenten, không phải Students.','Die Tasche ___ Lehrers ist neu.','des','dem','Dem là Dativ, không thể hiện Genitiv sở hữu trong mẫu này.','den','Den không phải Genitiv giống đực số ít.')
unit('Genitiv s bei Namen',24,'Tên riêng thường thêm -s để chỉ sở hữu: Annas Buch, Peters Wohnung. Tên kết thúc bằng s/ß/x/z thường chỉ thêm dấu nháy: Max’ Auto. Không dùng dấu nháy kiểu tiếng Anh với tên Anna trong chính tả Đức thông thường.','Annas Bruder wohnt hier.','Anh/em trai của Anna sống ở đây.','Anna\'s Bruder không phải mẫu sở hữu chuẩn thông thường cần học; dùng Annas Bruder.','Điền dạng sở hữu của Anna: ___ Buch.','Annas','Anna\'s','Không chèn dấu nháy trước s trong mẫu sở hữu thông thường này.','Annas\'','Tên Anna không cần dấu nháy sau s.')
unit('Dem oder den',3,'Dem là Dativ đực/trung số ít; den là Akkusativ đực số ít hoặc Dativ số nhiều. Để chọn, cần biết cả cách và số: mit dem Mann, für den Mann, mit den Männern. Den không đồng nghĩa luôn Akkusativ.','Ich spreche mit dem Mann.','Tôi nói chuyện với người đàn ông.','Mit den Mann sai ở số ít; nếu số nhiều phải là mit den Männern với biến đổi danh từ tương ứng.','Ich fahre mit ___ Bus. (der; số ít)','dem','den','Mit đòi Dativ, Bus ở số ít nên dem.','der','Der không phải Dativ đực số ít.')
unit('Deklination',13,'Biến cách là thay dạng theo cách, giống, số: mạo từ, đại từ, tính từ và một số danh từ cùng thể hiện quan hệ ngữ pháp. Xác định vai trò hoặc giới từ trước, rồi nhìn dấu hiệu mạo từ để chia tính từ.','Ich spreche mit einem netten Kollegen.','Tôi nói chuyện với một đồng nghiệp dễ mến.','Mit einem nette Kollege sai cả đuôi tính từ và danh từ yếu: cần netten Kollegen.','Mit einem ___ Kollegen. (nett)','netten','netter','Sau einem ở Dativ, tính từ dùng đuôi yếu -en.','nettes','-es không thuộc Dativ sau einem.')
unit('Adjektivdeklination|mit bestimmtem Artikel',13,'Sau der/die/das hoặc từ có tín hiệu tương đương, tính từ chủ yếu mang đuôi yếu -e/-en. Nominativ đực/cái/trung: der gute Wein, die gute Suppe, das gute Brot; số nhiều die guten Bücher. Tính từ vị ngữ không theo bảng này.','Ich kaufe den frischen Salat.','Tôi mua món salad tươi.','Den frisch Salat thiếu đuôi; den frische Salat dùng sai -e ở Akkusativ đực.','Ich kaufe den ___ Salat. (frisch)','frischen','frische','Akkusativ đực sau den dùng -en.','frischer','-er là tín hiệu mạnh, không dùng sau den trong mẫu này.')
unit('mit unbestimmtem Artikel',13,'Sau ein/kein/mein, tính từ mang tín hiệu mạnh khi từ trước chưa có tín hiệu: ein guter Wein, ein gutes Brot. Khi mạo từ đã có đuôi rõ, tính từ dùng đuôi yếu: einen guten Wein, mit einem guten Freund.','Das ist ein interessantes Buch.','Đó là một quyển sách thú vị.','Ein ở Nominativ trung không thể hiện -s, nên tính từ phải mang -es. Không viết ein interessante Buch.','Das ist ein ___ Buch. (interessant)','interessantes','interessante','Ein chưa đánh dấu trung nên tính từ cần -es.','interessanten','-en không phải đuôi ở Nominativ trung sau ein.')
unit('ohne Artikel',13,'Không có mạo từ, tính từ thường mang đuôi mạnh thể hiện giống/cách/số: guter Wein, frische Milch, mit kaltem Wasser. Ở Genitiv đực/trung, dạng tính từ thường có -en: guten Weines; không đồng nhất bảng mạnh với bảng mạo từ ở mọi ô.','Ich trinke kaltes Wasser.','Tôi uống nước lạnh.','Wasser trung Akkusativ không mạo từ nên kaltes, không phải kalte.','Ich trinke ___ Wasser. (kalt)','kaltes','kalte','Trung Akkusativ không mạo từ cần -es.','kalter','-er không dùng cho trung Akkusativ này.')
unit('mit Komparativ und Superlativ',14,'Trước danh từ, cấp so sánh vẫn phải biến cách: ein größerer Raum; der größte Raum; in einem größeren Raum. Tách gốc so sánh khỏi đuôi: größ-er-en. Am größten là dạng vị ngữ/trạng ngữ, không gắn trực tiếp trước Raum.','Wir brauchen einen größeren Raum.','Chúng ta cần một phòng lớn hơn.','Einen größer Raum thiếu đuôi -en sau phần so sánh -er. Không viết einen am größten Raum.','Wir brauchen einen ___ Raum. (groß; hơn)','größeren','größer','Thiếu đuôi biến cách -en sau einen.','am größten','Đây là dạng vị ngữ/trạng ngữ, không dùng trực tiếp trước Raum.')
unit('Komparation mit wie und als',14,'Bằng nhau: so/genauso + tính từ + wie. Khác mức độ: Komparativ + als. Khi hai cụm là chủ ngữ so sánh, dùng Nominativ: größer als ich. Trong văn nói có biến thể vùng, khi viết chuẩn ưu tiên quy tắc này.','Sie ist so groß wie ich.','Cô ấy cao bằng tôi.','Nicht größer wie trong văn viết chuẩn; dùng größer als. So groß als cũng sai cặp tương quan ở mẫu bằng nhau.','Sie ist größer ___ ich.','als','wie','Wie dùng với so groß, không phải Komparativ größer trong chuẩn viết.','dass','Dass mở mệnh đề nội dung, không nối so sánh danh ngữ này.')
unit('Unregelmäßige Adjektive',14,'Học các dãy đặc biệt: gut–besser–am besten; viel–mehr–am meisten; gern–lieber–am liebsten (gern là trạng từ); hoch–höher–am höchsten; nah–näher–am nächsten. Không ghép đuôi -er đều lên mọi dạng.','Dieser Plan ist besser.','Kế hoạch này tốt hơn.','Nicht guter khi muốn nói hơn của gut; guter có thể là tính từ biến cách trong ein guter Plan, nghĩa khác.','Der neue Plan ist ___. (gut; hơn)','besser','guter','Guter là dạng biến cách, không phải Komparativ của gut.','am besten','Đây là so sánh nhất, không phải hơn.')
unit('Graduierung von Adjektiven',14,'Mức độ có thể biểu thị bằng sehr, ziemlich, etwas, äußerst hoặc so sánh. Nicht sehr gut khác với sehr schlecht; cực tính và phủ định không hoán đổi tùy ý. Một số tính từ tuyệt đối ít dùng so sánh trong nghĩa đen nhưng vẫn có cách dùng tu từ.','Die Aufgabe ist ziemlich schwierig.','Bài tập khá khó.','Zu schwierig nghĩa quá khó so với một chuẩn/mục tiêu; sehr schwierig chỉ rất khó. Đừng dịch cả hai như nhau.','Die Tasche ist ___ schwer, ich kann sie nicht tragen. (quá)','zu','sehr','Sehr chỉ mức độ cao, chưa trực tiếp biểu thị vượt ngưỡng như yêu cầu quá.','am','Am không tự làm trạng từ mức độ trước schwer.')
unit('Negative Adjektive',50,'Tiền tố un-, hậu tố -los và từ trái nghĩa có thể tạo nghĩa phủ định: unfreundlich, arbeitslos, unbekannt. Không phải mọi tính từ đều nhận un-; nicht unzufrieden thường nhẹ hơn zufrieden, tùy ngữ cảnh. Học từ như đơn vị từ vựng.','Die Antwort ist unvollständig.','Câu trả lời chưa đầy đủ.','Unvollständig không đồng nghĩa falsch: có thể thiếu mà phần đã viết vẫn đúng. Không tạo un- tùy ý cho mọi tính từ.','Điền từ nghĩa “không đầy đủ”: Die Antwort ist ___.','unvollständig','vollständig','Vollständig là đầy đủ, trái nghĩa yêu cầu.','arbeitslos','Arbeitslos nói thất nghiệp, không nói độ đầy đủ của câu trả lời.')
unit('Nominalisierte Adjektive',51,'Tính từ danh từ hóa viết hoa nhưng giữ quy tắc đuôi: der Arbeitslose, ein Arbeitsloser, etwas Neues, die Reisenden. Mạo từ hoặc lượng từ trước nó quyết định dạng mạnh/yếu. Không thêm một danh từ không có trong ý gốc.','Ich habe etwas Neues gelernt.','Tôi đã học được điều gì đó mới.','Etwas neue sai vì danh từ hóa trung sau etwas cần -es và viết hoa.','Ich habe etwas ___ gelernt. (neu)','Neues','neue','Thiếu viết hoa và đuôi -es của tính từ danh từ hóa.','Neuen','-en không dùng ở mẫu etwas + tính từ trung này.')
unit('Nominalisierung',51,'Danh từ hóa biến hành động/tính chất thành danh ngữ: prüfen → die Prüfung; lesen → das Lesen. Phải giữ quan hệ nghĩa: die Prüfung des Antrags, không tự đổi người thực hiện thành đối tượng. Dùng khi cần nén thông tin, tránh danh ngữ quá dài.','Nach der Prüfung des Antrags erhalten Sie eine Antwort.','Sau khi đơn được xem xét, bạn sẽ nhận được phản hồi.','Danh từ hóa không chỉ viết hoa động từ: sau nach cần Dativ và một danh ngữ đúng cấu trúc.','Beim ___ mache ich Notizen. (lesen)','Lesen','lesen','Sau beim, nguyên mẫu được danh từ hóa và viết hoa.','gelesen','Gelesen là Partizip II, không phải danh từ nguyên mẫu trong mẫu này.')
unit('Adverbien|Modaladverbien',31,'Trạng từ bổ sung thời gian, nơi chốn, cách thức hoặc đánh giá. Khi dùng để bổ nghĩa động từ, tính từ/trạng từ không thêm đuôi: Sie arbeitet sorgfältig. So sánh sorgfältiger vẫn có thể dùng, nhưng không thêm đuôi định ngữ khi không đứng trước danh từ.','Sie arbeitet sehr sorgfältig.','Cô ấy làm việc rất cẩn thận.','Nicht Sie arbeitet sorgfältige; đuôi tính từ thuộc eine sorgfältige Mitarbeiterin, không thuộc cách thức làm.','Sie arbeitet ___. (sorgfältig)','sorgfältig','sorgfältige','Đây là cách thức hành động, không phải định ngữ trước danh từ.','sorgfältigen','Đuôi -en không cần khi dùng trạng ngữ.')
unit('Lokaladverbien',31,'Hier/dort nói vị trí, hierher/dorthin nói hướng đến, von hier/von dort nói xuất phát. Cặp hin/her phụ thuộc điểm nhìn; dùng đâu và đi đâu không hoán đổi. Trạng từ không cần thêm giới từ trong mọi trường hợp.','Komm bitte hierher!','Hãy đến đây nhé!', 'Hierher là hướng về chỗ người nói; hier đơn thuần nói vị trí. Không viết zu hierher.','Komm bitte ___! (đến đây)','hierher','hier','Hier chỉ vị trí, không rõ hướng đến như yêu cầu.','von hier','Von hier là xuất phát từ đây.')
unit('Hinauf – herauf, hinunter – herunter, hinab – herab',31,'Hin chỉ hướng ra xa điểm nhìn, her hướng về điểm nhìn; auf lên, unter/ab xuống. Người ở trên gọi người dưới: Komm herauf! Người nói hướng ai lên nơi khác: Geh hinauf! Văn nói thường dùng rauf/runter nên mất phân biệt hin/her.','Komm zu mir herauf!','Hãy lên chỗ tôi!', 'Chọn theo vị trí người nói, không chỉ dịch lên/xuống. Hinauf và herauf đều lên nhưng khác điểm quy chiếu.','Người ở trên gọi: Komm zu mir ___!','herauf','hinauf','Hin hướng ra xa điểm nhìn, trái với zu mir ở tình huống này.','herunter','Herunter hướng xuống, trong khi người nói ở trên.')
unit('Temporaladverbien',31,'Heute/gestern/morgen xác định ngày; schon/noch/erst nêu kỳ vọng hoặc tiến trình; danach/vorher định vị tương đối với sự kiện khác. Khi một trạng từ chiếm Vorfeld, động từ vẫn V2. Không thêm một thành phần độc lập nữa trước động từ.','Morgen fahre ich nach Berlin.','Ngày mai tôi đi Berlin.','Morgen ich fahre vi phạm V2. Morgen có thể là cả một thành phần, không tính theo số từ.','Morgen ___ ich nach Berlin. (fahren)','fahre','ich fahre','Ich đã có sau chỗ trống; chèn lại tạo hai chủ ngữ và sai V2.','fahren','Ich cần fahre, không phải nguyên mẫu.')
unit('Präpositionen',7,'Giới từ đi với một cụm bổ ngữ và chi phối cách. Học kết hợp: mit + Dativ, für + Akkusativ, wegen thường Genitiv trong chuẩn viết. Một số giới từ đổi Dativ/Akkusativ theo nghĩa vị trí/đích. Không dịch từng giới từ rồi đoán cách.','Ich fahre mit dem Zug.','Tôi đi bằng tàu hỏa.','Mit den Zug sai vì Zug số ít và mit luôn Dativ trong nghĩa này.','Ich fahre mit ___ Zug. (der)','dem','den','Mit + Dativ, không phải Akkusativ.','des','Mit không đòi Genitiv.')
unit('Präpositionen mit Akkusativ',7,'Durch, für, gegen, ohne, um thường dùng Akkusativ: durch den Park, für einen Freund, ohne mich. Cách do giới từ chi phối, không phụ thuộc chuyển động có xảy ra hay không. Bis thường có cấu trúc riêng khi kết hợp giới từ khác: bis zum Bahnhof.','Das Geschenk ist für meinen Vater.','Món quà dành cho bố tôi.','Für meinem Vater sai vì für không dùng Dativ. Không áp quy tắc wo/wohin lên für.','Das ist für ___ Vater. (mein)','meinen','meinem','Für đòi Akkusativ, không phải Dativ.','meiner','Meiner không phải Akkusativ đực ở đây.')
unit('Präpositionen mit Dativ',7,'Aus, bei, mit, nach, seit, von, zu dùng Dativ trong các mẫu cơ bản: bei der Ärztin, seit einem Jahr. Seit nói kéo dài từ mốc quá khứ, thường đi với Präsens nếu còn tiếp diễn. Không đổi cách chỉ vì câu có chuyển động.','Ich gehe zu meinem Freund.','Tôi đến chỗ bạn tôi.','Dù có đi đến, zu vẫn Dativ. Wo/wohin không quyết định cách của giới từ có cách cố định.','Ich gehe zu ___ Freund. (mein)','meinem','meinen','Zu luôn đòi Dativ ở đây, dù có chuyển động.','meines','Meines là Genitiv, không đúng sau zu.')
unit('Präpositionen mit Genitiv',57,'Trong văn viết, wegen, trotz, während, aufgrund, innerhalb, außerhalb thường đi với Genitiv. Cần phân biệt während + danh ngữ với während + mệnh đề. Một số giới từ có Dativ trong biến thể khẩu ngữ; khi viết trang trọng, ưu tiên mẫu Genitiv rõ.','Wegen des Sturms fällt der Zug aus.','Do bão, chuyến tàu bị hủy.','Des Sturm thiếu -s: des Sturms. Không áp -s cho danh từ yếu như des Studenten.','Wegen ___ Sturms bleibt er zu Hause.','des','den','Den không phải Genitiv đực số ít.','das','Das không phải mạo từ của Sturm, cũng không đánh dấu Genitiv.')
unit('Lokale Präpositionen|Wechselpräpositionen',35,'An, auf, hinter, in, neben, über, unter, vor, zwischen dùng Dativ cho vị trí và Akkusativ cho đích đổi vị trí. Ngoài ra nach thường chỉ quốc gia/thành phố không mạo từ, zu chỉ hướng đến người/địa điểm hoạt động, in thường nói vào bên trong.','Wir gehen in den Park.','Chúng tôi đi vào công viên.','Wir laufen im Park là hoạt động trong công viên, vẫn Dativ. Không đồng nhất mọi động từ chuyển động với Akkusativ.','Wir sind in ___ Park. (der)','dem','den','Sind mô tả vị trí, không phải đi vào.','des','In trong nghĩa này không chi phối Genitiv.')
unit('Modale Präpositionen',7,'Mit thường chỉ phương tiện/công cụ: mit dem Zug, mit einem Messer; ohne chỉ thiếu thành phần: ohne Zucker. Durch có thể nói phương thức/tác động; per có cách dùng cố định riêng. Không phải mọi bằng tiếng Việt đều dịch thành mit.','Er öffnet die Tür mit einem Schlüssel.','Anh ấy mở cửa bằng một chiếc chìa khóa.','Mit cần Dativ: einem Schlüssel, không phải einen Schlüssel.','Er schreibt mit ___ Stift. (ein)','einem','einen','Mit yêu cầu Dativ; einen là Akkusativ.','eines','Eines là Genitiv, không dùng ở đây.')
unit('Temporale Präpositionen',7,'Am với ngày/buổi: am Montag, am Morgen; um với giờ: um acht Uhr; im với tháng/mùa: im Mai, im Sommer. In der Nacht là ngoại lệ cần học. Seit chỉ kéo dài từ mốc, vor nói cách đây, für nói khoảng thời gian dự kiến.','Der Kurs beginnt am Montag um neun Uhr.','Khóa học bắt đầu lúc chín giờ thứ Hai.','Im Montag sai; dùng am Montag. Nachts là trạng từ, không cần thêm am trước nó.','Der Kurs beginnt ___ Montag.','am','im','Im không dùng với tên ngày tuần ở mẫu này.','um','Um thường đi với giờ cụ thể, không với Montag.')
unit('Am Mittag oder zu Mittag',7,'Am Mittag chỉ thời điểm buổi trưa. Zu Mittag thường đi với essen trong kết hợp ăn trưa: Wir essen zu Mittag. Cũng có Mittag essen; am Mittag essen có thể nói ăn vào lúc trưa. Không tuyên bố một trong hai luôn sai.','Wir essen zu Mittag.','Chúng tôi ăn trưa.','Zu Mittag essen là một kết hợp cố định; am Mittag nhấn thời gian. Phân biệt ý định thay vì thay tất cả am bằng zu.','Cụm cố định ăn trưa: Wir essen ___ Mittag.','zu','mit','Mit không tạo cụm cố định ăn trưa.','für','Für Mittag không phải kết hợp cố định đang hỏi.')
unit('Verben|Infinitiv|Regelmäßige und unregelmäßige Verben',0,'Nguyên mẫu thường có -en/-n: machen, sammeln. Động từ đã chia thể hiện ngôi/số/thì. Động từ đều có mẫu ổn định; động từ mạnh có thể đổi nguyên âm hoặc Partizip II. Không suy mọi dạng chỉ từ nguyên mẫu; học ba dạng với động từ bất quy tắc.','Ich lerne Deutsch.','Tôi học tiếng Đức.','Ich lernen sai chia ngôi. Ich lernte là Präteritum, không phải Präsens.','Ich ___ Deutsch. (lernen; Präsens)','lerne','lernen','Ich ở Präsens dùng -e, không phải nguyên mẫu.','lernst','-st dành cho du, không phải ich.')
unit('Präsens',0,'Präsens diễn đạt hiện tại, thói quen và cả tương lai khi có mốc. Mẫu đều: ich -e, du -st, er/sie/es -t, wir -en, ihr -t, sie/Sie -en. Gốc tận cùng -t/-d thường cần thêm e để phát âm: du arbeitest.','Morgen arbeite ich zu Hause.','Ngày mai tôi làm việc ở nhà.','Tương lai không bắt buộc Futur I. Ihr arbeitet khác er arbeitet ở chủ ngữ nhưng hình thức có thể giống.','Du ___ heute. (arbeiten)','arbeitest','arbeitst','Gốc arbeit- cần thêm e trước -st.','arbeiten','Du cần dạng đã chia, không phải nguyên mẫu.')
unit('Sein und haben im Präsens',0,'Sein: bin, bist, ist, sind, seid, sind. Haben: habe, hast, hat, haben, habt, haben. Hai động từ vừa có nghĩa riêng vừa làm trợ động từ; không dùng mẫu đều bằng cách thêm -e vào sein.','Ich bin müde und habe Hunger.','Tôi mệt và đói.', 'Tiếng Đức nói Hunger haben, không Hunger sein. Seid là động từ của ihr, seit là từ chỉ thời gian.','Ihr ___ heute hier. (sein)','seid','seit','Seit là giới từ/liên từ thời gian, không phải động từ.','sind','Sind dùng với wir/sie/Sie, không phải ihr.')
unit('Präteritum von haben und sein',16,'Sein → war, warst, war, waren, wart, waren. Haben → hatte, hattest, hatte, hatten, hattet, hatten. Hai dạng này dùng nhiều trong cả lời nói kể chuyện. Không tạo bằng cách thêm -te trực tiếp vào sein hoặc dùng ist để nói quá khứ đã kết thúc.','Gestern war ich krank und hatte Fieber.','Hôm qua tôi bị ốm và sốt.','Ich hatte krank sai kết hợp: krank đi với sein; Fieber đi với haben.','Gestern ___ ich krank. (sein)','war','hatte','Krank là vị ngữ tính từ, ở đây dùng war chứ không hatte.','wäre','Wäre là Konjunktiv II, không phải quá khứ thực tế đang hỏi.')
unit('Verben mit Vokalwechsel',0,'Một số động từ mạnh đổi nguyên âm ở du và er/sie/es trong Präsens: fahren → fährst/fährt; lesen → liest/liest; sprechen → sprichst/spricht. Wir/ihr/sie thường không đổi như vậy. Học theo từng động từ, không đổi mọi a/e.','Er liest jeden Abend.','Anh ấy đọc mỗi tối.','Ihr fährt sai: phải ihr fahrt. Vokalwechsel không lan sang mọi ngôi.','Er ___ nach Berlin. (fahren)','fährt','fahrt','Fahrt dành cho ihr hoặc Imperativ ihr; er cần Umlaut.','fahren','Er cần dạng ngôi ba số ít.')
unit('Trennbare Verben',5,'Tiền tố tách ở câu chính: aufstehen → Ich stehe früh auf. Khi có Modalverb, nguyên mẫu ở cuối: Ich muss früh aufstehen. Trong câu phụ, động từ đã chia viết liền ở cuối: weil ich früh aufstehe.','Ich rufe dich morgen an.','Ngày mai tôi gọi cho bạn.','Ich anrufe dich trong câu chính sai tách/V2. Partizip II thường thêm ge ở giữa: angerufen.','Ich stehe um sieben ___. (aufstehen)','auf','aufstehen','Động từ chính stehe đã chia; cuối câu chỉ còn tiền tố auf.','geauf','Không có dạng tiền tố geauf trong Präsens.')
unit('Verben mit Akkusativ',3,'Lernen/kaufen/besuchen/sehen/anrufen thường có tân ngữ Akkusativ. Không phải mỗi câu đều phải hiện tân ngữ; khi có, cách do động từ và nghĩa chi phối. Đại từ người nam: ihn, không phải ihm.','Ich besuche meinen Onkel.','Tôi thăm chú/bác/cậu của tôi.','Besuchen + Akkusativ, không phải Dativ chỉ vì tân ngữ là người.','Ich besuche ___. (er)','ihn','ihm','Ihm là Dativ; besuchen cần Akkusativ.','er','Er là Nominativ, không phải tân ngữ ở đây.')
unit('Verben mit Dativ',3,'Helfen, danken, gefallen, gehören, folgen đòi Dativ trong các nghĩa cơ bản. Người giúp là chủ ngữ, người được giúp Dativ. Với gefallen, thứ được thích làm chủ ngữ: Das Buch gefällt mir.','Das Buch gefällt mir.','Tôi thích quyển sách này.','Ich gefalle das Buch không diễn đạt tôi thích sách; gefallen có cấu trúc khác mögen.','Ich danke ___. (du)','dir','dich','Danken đòi Dativ, dich là Akkusativ.','du','Du là Nominativ, không phải người nhận lời cảm ơn.')
unit('Verben mit Dativ und Akkusativ',41,'Geben/schenken/zeigen/schicken thường có người nhận Dativ và vật Akkusativ. Hai danh từ thường Dativ trước Akkusativ; nếu cả hai là đại từ không nhấn, Akkusativ thường đứng trước Dativ: Ich gebe es ihm. Ngữ cảnh có thể thay đổi trọng tâm.','Ich gebe es ihm.','Tôi đưa nó cho anh ấy.','Ich gebe ihm es không phải thứ tự trung hòa với hai đại từ không nhấn. Không coi thứ tự danh từ là quy tắc cho mọi đại từ.','Ich gebe ___ das Buch. (er; người nhận)','ihm','ihn','Người nhận là Dativ, không phải ihn.','er','Chủ ngữ đã là ich; er không làm bổ ngữ người nhận.')
unit('Verb kommen',0,'Kommen chia komme, kommst, kommt, kommen, kommt, kommen; Perfekt dùng sein: ist gekommen. Woher kommst du? hỏi nguồn gốc; Wann kommst du? hỏi thời điểm đến. Đích đến chọn giới từ theo địa điểm, không theo động từ riêng lẻ.','Er ist gestern gekommen.','Anh ấy đã đến hôm qua.','Er hat gekommen sai trợ động từ trong nghĩa đến. Không viết gekommt thay gekommen.','Er ist gestern ___. (kommen)','gekommen','gekommt','Kommen có Partizip II bất quy tắc gekommen.','kommen','Đây là nguyên mẫu, không phải Partizip II của Perfekt.')
unit('Verb hängen',35,'Phân biệt tự treo ở trạng thái: Das Bild hängt, hing, hat gehangen; treo một vật: Ich hänge das Bild auf, hängte auf, habe aufgehängt. Hình thức Präsens gần giống nhưng vai trò và quá khứ khác nhau.','Das Bild hängt an der Wand.','Bức tranh treo trên tường.','Trạng thái dùng wo + Dativ: an der Wand. Đặt/treo vào vị trí dùng wohin + Akkusativ: an die Wand.','Das Bild hängt an ___ Wand. (die)','der','die','Hängt mô tả vị trí, không phải đích đặt vật.','den','Wand cái số ít, Dativ không phải den.')
unit('Verb werden',30,'Werden là động từ trở thành, trợ động từ Futur I và trợ động từ bị động. Phân biệt: Er wird Arzt; er wird arbeiten; er wird untersucht. Partizip II khi là động từ chính: geworden; ở Perfekt bị động: worden.','Er ist Arzt geworden.','Anh ấy đã trở thành bác sĩ.','Er ist untersucht geworden không phải mẫu Perfekt bị động chuẩn đang học: er ist untersucht worden.','Er ist Lehrer ___. (trở thành)','geworden','worden','Worden dùng trong Perfekt bị động, không phải werden nghĩa trở thành.','werden','Werden là nguyên mẫu, không phải Partizip II ở đây.')
unit('Modalverben',4,'Modalverb đã chia ở V2, động từ nguyên mẫu thường đứng cuối không có zu: Ich kann schwimmen. Các ngôi ich/er thường không có đuôi -e/-t ở Präsens: ich muss, er kann. Phủ định có thể đổi nghĩa mạnh: nicht müssen khác nicht dürfen.','Ich kann heute nicht kommen.','Hôm nay tôi không thể đến.','Ich kann zu kommen sai vì können đi với nguyên mẫu không zu. Nicht müssen là không cần, không phải cấm.','Ich kann heute nicht ___. (kommen)','kommen','zu kommen','Können đi với nguyên mẫu không zu.','gekommen','Partizip II không thuộc mẫu Modalverb hiện tại này.')
unit('Modalverb dürfen',4,'Dürfen chỉ sự cho phép, phủ định nicht dürfen chỉ cấm. Ich darf, du darfst, er darf, wir dürfen, ihr dürft. Dürfte còn có thể là Konjunktiv II lịch sự/phỏng đoán ở mức cao hơn, không đồng nhất với Präsens dürfen.','Hier darf man nicht rauchen.','Ở đây không được hút thuốc.','Không dùng nicht müssen để diễn đạt cấm: nó chỉ không bắt buộc.','Hier ___ man nicht rauchen. (cấm)','darf','muss','Nicht müssen là không cần, không phải cấm.','will','Nicht wollen là không muốn, không diễn đạt quy định cấm.')
unit('Modalverb können',4,'Können chỉ khả năng, năng lực hoặc cơ hội. Ich kann, du kannst, er kann, wir können, ihr könnt. Để xin phép, kann có trong thực tế nhưng dürfen nêu quyền cho phép rõ hơn. Nguyên mẫu đứng cuối không zu.','Sie kann gut schwimmen.','Cô ấy bơi giỏi.','Er könnt sai chia ngôi; könnt thuộc ihr. Không thêm -t vào er kann.','Er ___ gut schwimmen. (können)','kann','könnt','Könnt thuộc ihr, không phải er.','kannst','Kannst thuộc du.')
unit('Modalverb möchten/mögen',4,'Mögen: thích, thường đi với danh từ hoặc động từ trong một số nghĩa. Möchten là dạng Konjunktiv II của mögen được dùng thông dụng cho mong muốn lịch sự: Ich möchte einen Tee. Không có nguyên mẫu möchten tiêu chuẩn để suy mọi thì; quá khứ ý muốn thường dùng wollte.','Ich möchte einen Tee.','Tôi muốn một tách trà.','Ich möchte là muốn lịch sự, không phải đơn giản tôi thích trà nói chung. Ich mag Tee mới là thích trà.','Ich ___ gern einen Tee. (mong muốn lịch sự)','möchte','magst','Magst thuộc du và không diễn đạt đúng dạng yêu cầu lịch sự.','möchtet','Möchtet thuộc ihr, không phải ich.')
unit('Modalverb müssen',4,'Müssen chỉ nghĩa vụ/sự cần thiết; nicht müssen nghĩa không cần. Không được làm phải dùng nicht dürfen. Ở mức nâng cao, muss có thể chỉ suy đoán chắc chắn; xác định nghĩa từ ngữ cảnh.','Du musst heute nicht arbeiten.','Hôm nay bạn không cần làm việc.','Câu này không có nghĩa hôm nay bạn bị cấm làm việc; đó là du darfst heute nicht arbeiten.','Nghĩa của “Du musst nicht kommen” là gì?','Bạn không cần đến.','Bạn bị cấm đến.','Cấm phải dùng nicht dürfen, không phải nicht müssen.','Bạn nhất định phải đến.','Nicht phủ định sự cần thiết trong câu này.')
unit('Modalverb sollen',4,'Sollen thường chỉ lời yêu cầu, lời khuyên hoặc nhiệm vụ từ người khác. Ich soll den Arzt anrufen: ai đó yêu cầu/khuyên tôi gọi bác sĩ. Sollte thường nhẹ hơn và có thể làm lời khuyên. Nâng cao: soll còn dẫn thông tin nghe nói.','Der Arzt sagt, ich soll mich ausruhen.','Bác sĩ nói tôi nên nghỉ ngơi.','Sollen không tự có nghĩa muốn; wollen mới nêu ý muốn của chủ thể. Không trộn hai nguồn nghĩa vụ này.','Ich ___ laut Arzt mehr schlafen. (sollen)','soll','will','Will nói ý muốn của ich, không chuyển lời yêu cầu của bác sĩ.','sollst','Sollst thuộc du, không phải ich.')
unit('Modalverb wollen',4,'Wollen diễn đạt ý định/mong muốn khá trực tiếp. Ich will, du willst, er will, wir wollen, ihr wollt. Khi gọi món hoặc nhờ vả, möchte thường mềm hơn will; không coi will là sai ngữ pháp nhưng cần chọn sắc thái.','Wir wollen morgen verreisen.','Chúng tôi định đi xa ngày mai.','Er willt sai vì ngôi ba số ít là will, không thêm -t.','Er ___ morgen kommen. (wollen)','will','willt','Wollen ở er dùng will, không thêm -t.','willst','Willst thuộc du.')
unit('Modalverben im Präteritum',16,'Können→konnte, müssen→musste, dürfen→durfte, sollen→sollte, wollen→wollte, mögen→mochte. Các dạng này thông dụng khi kể chuyện. Phân biệt konnte (đã có thể) với könnte (giả định/lịch sự), musste với müsste.','Gestern konnte ich nicht kommen.','Hôm qua tôi không thể đến.','Đừng bỏ qua Umlaut: könnte không phải dạng Präteritum của können mà là Konjunktiv II.','Gestern ___ ich arbeiten. (müssen; Präteritum)','musste','müsste','Müsste là Konjunktiv II, không phải quá khứ thực tế.','muss','Muss là Präsens.')
unit('Perfekt mit Modalverben',47,'Có nguyên mẫu đi kèm, Perfekt thường dùng Ersatzinfinitiv: Ich habe arbeiten müssen, không gemusst ở mẫu này. Khi đứng độc lập không có động từ nguyên mẫu bổ sung, Partizip II có thể dùng: Das habe ich nicht gewollt. Trong câu phụ có cụm kép, trợ động từ đứng trước cụm nguyên mẫu.','Ich habe gestern arbeiten müssen.','Hôm qua tôi đã phải làm việc.','Weil ich habe arbeiten müssen: habe đứng trước hai nguyên mẫu; không chuyển máy móc thành arbeiten müssen habe.','Ich habe gestern arbeiten ___. (müssen)','müssen','gemusst','Có arbeiten đi kèm nên dùng Ersatzinfinitiv müssen.','musste','Musste là dạng hữu hạn Präteritum, không thuộc cụm Perfekt này.')
unit('Verb brauchen',30,'Brauchen nghĩa cần có thể đi với Akkusativ: Ich brauche Hilfe. Với phủ định/giới hạn, brauchen + zu + Infinitiv diễn đạt không cần: Du brauchst nicht zu warten. Khẩu ngữ có thể bỏ zu; khi viết chuẩn hãy dùng mẫu có zu.','Du brauchst nicht zu warten.','Bạn không cần chờ.','Không dịch nicht brauchen thành cấm. Du darfst nicht warten mới nêu không được phép chờ.','Du brauchst nicht ___ warten.','zu','um','Um cần cấu trúc mục đích khác, không phải thành phần của brauchen.','dass','Dass mở mệnh đề có động từ chia, không đứng trước warten như vậy.')
unit('Verb lassen',30,'Lassen + Infinitiv không zu có nghĩa cho phép, để, nhờ người làm: Ich lasse mein Fahrrad reparieren. Sich lassen có thể chỉ khả năng bị động: Das lässt sich erklären. Không phải lúc nào cũng là tự mình làm hành động.','Ich lasse mein Fahrrad reparieren.','Tôi đem/nhờ sửa xe đạp.','Lassen reparieren cho biết người khác sửa; không đồng nghĩa ich repariere tự sửa.','Ich lasse mein Fahrrad ___. (reparieren)','reparieren','zu reparieren','Sau lassen ở mẫu này không có zu.','repariert','Cần nguyên mẫu, không phải Partizip II.')
unit('Indikativ',0,'Indikativ là thức dùng trình bày sự việc được nêu như thực, gồm nhiều thì. Không nhầm thức với thì: ich ging là Indikativ Präteritum, ich wäre gegangen là Konjunktiv II quá khứ. Indikativ không bảo đảm phát ngôn đúng ngoài đời; nó là cách trình bày ngữ pháp.','Sie ist heute zu Hause.','Hôm nay cô ấy ở nhà.','Ist và wäre khác thức chứ không đơn giản là hiện tại và quá khứ. Phải xem cả cụm động từ.','Chọn dạng Indikativ Präsens của sein với sie số ít.','ist','wäre','Wäre là Konjunktiv II, không phải Indikativ Präsens.','sei','Sei là Konjunktiv I hoặc Imperativ tùy ngữ cảnh.')
unit('Imperativ',6,'Mệnh lệnh có các dạng du, ihr, Sie: Komm! Kommt! Kommen Sie! Du thường bỏ đại từ; Sie giữ đại từ lịch sự. Động từ tách đặt tiền tố cuối: Ruf mich an! Sein có dạng đặc biệt sei/seid/seien Sie.','Kommen Sie bitte herein!','Mời ông/bà vào!', 'Không dùng du kommst như dạng Imperativ trung hòa; đó là câu trần thuật có thể dùng như mệnh lệnh theo ngữ điệu, chức năng khác.','___ bitte ruhig! (sein; du)','Sei','Bist','Bist là Indikativ với du, không phải dạng mệnh lệnh.','Sind','Sind không phải Imperativ du.')
unit('Partizip 2',12,'Partizip II dùng trong Perfekt, bị động và làm định ngữ. Đều: gemacht; mạnh: geschrieben; tiền tố không tách be-/ver-/er- thường không ge: bezahlt; động từ -ieren không ge: studiert; tách: aufgemacht. Không đồng nhất Partizip II với thì quá khứ đứng độc lập.','Ich habe Deutsch gelernt.','Tôi đã học tiếng Đức.','Ich habe lernen sai vì Perfekt thông thường cần Partizip II; Ersatzinfinitiv với Modalverb là trường hợp riêng.','Partizip II của studieren là ___.','studiert','gestudiert','Động từ tận cùng -ieren không thêm ge-.','studieren','Studieren là nguyên mẫu.')
unit('Partizip 1',36,'Partizip I = nguyên mẫu + d: warten→wartend. Khi làm định ngữ, thêm đuôi tính từ: die wartenden Gäste. Thường mang nghĩa chủ động/đang xảy ra, nhưng thời gian tương đối phụ thuộc động từ chính. Phân biệt với Partizip II hoàn tất/kết quả.','Die wartenden Gäste stehen vor der Tür.','Những vị khách đang đợi đứng trước cửa.','Wartende và gewartete không đồng nghĩa: warten còn có nghĩa bảo dưỡng khi dùng chuyển tác.','Die ___ Gäste stehen hier. (warten; Partizip I)','wartenden','gewarteten','Đây là Partizip II của warten trong nghĩa khác, không diễn đạt những người đang đợi.','wartend','Trước Gäste cần thêm đuôi tính từ -en sau die.')
unit('Perfekt',12,'Perfekt = haben/sein đã chia + Partizip II cuối câu. Phần lớn động từ dùng haben; một số động từ đổi vị trí/trạng thái và sein/bleiben dùng sein. Chọn theo động từ và nghĩa: hat getanzt nhưng ist gefahren trong nghĩa đi đến.','Sie ist nach Hause gefahren.','Cô ấy đã đi về nhà.','Không phải động từ có vận động cơ thể đều dùng sein: tanzen thường haben, schwimmen tùy cách dùng. Học cả mẫu động từ.','Sie ___ nach Berlin gefahren.','ist','hat','Ở nghĩa đi đến Berlin, fahren dùng sein.','wird','Wird + gefahren sẽ là cấu trúc bị động khác, không phải Perfekt này.')
unit('Präteritum',16,'Präteritum đều: gốc + -te + đuôi; động từ mạnh đổi gốc: gehen→ging, schreiben→schrieb. Thường dùng trong văn kể chuyện, còn sein/haben/Modalverb phổ biến cả lời nói. Lựa chọn Perfekt/Präteritum không đơn giản là gần/xa trong thời gian.','Er schrieb gestern einen Brief.','Hôm qua anh ấy viết một lá thư.','Schreibte không phải Präteritum của schreiben; cần schrieb. Không suy mọi động từ có -te.','Er ___ einen Brief. (schreiben; Präteritum)','schrieb','schreibte','Schreiben là động từ mạnh, Präteritum không tạo bằng -te.','geschrieben','Geschrieben là Partizip II, cần trợ động từ nếu dùng Perfekt.')
unit('Plusquamperfekt',17,'Hatte/war + Partizip II đặt một sự việc trước một mốc quá khứ. Không dùng chỉ vì việc xảy ra rất lâu; phải có quan hệ trước–sau với mốc khác. Giữ trợ động từ như Perfekt, chỉ đổi haben/sein sang quá khứ.','Als ich ankam, war sie bereits gegangen.','Khi tôi đến, cô ấy đã đi rồi.','Sie hatte gegangen sai trợ động từ: gehen dùng sein trong nghĩa này nên war gegangen.','Als ich ankam, ___ sie schon gegangen.','war','hatte','Gehen dùng sein nên Plusquamperfekt là war gegangen.','wird','Wird không đặt sự việc trước một mốc quá khứ trong câu này.')
unit('Futur 1',20,'Futur I = werden đã chia + Infinitiv. Dùng cho dự báo, dự định hoặc phỏng đoán hiện tại; Präsens với trạng ngữ cũng thường diễn đạt tương lai. Không đồng nhất tất cả werden với Futur: wird repariert là bị động.','Ich werde morgen anrufen.','Ngày mai tôi sẽ gọi điện.','Ich werde angerufen mang nghĩa tôi được gọi; thay nguyên mẫu bằng Partizip II làm đổi cấu trúc sang bị động.','Ich werde morgen ___. (anrufen)','anrufen','angerufen','Angerufen tạo bị động với werde, không phải ý tôi sẽ gọi.','anrufe','Cần nguyên mẫu sau werden tạo Futur I, không phải dạng đã chia.')
unit('Futur 2',61,'Futur II = werden + Partizip II + haben/sein: wird gelesen haben, wird angekommen sein. Có thể nói hoàn tất trước mốc tương lai hoặc phỏng đoán về quá khứ. Mốc bis morgen khác với inzwischen; phải đọc ngữ cảnh thay vì chỉ dịch sẽ.','Bis Freitag werde ich den Bericht geschrieben haben.','Đến thứ Sáu, tôi sẽ viết xong báo cáo.','Er wird angekommen haben sai: ankommen dùng sein. Vị trí cuối chứa trợ động từ nguyên mẫu.','Er wird inzwischen angekommen ___.','sein','haben','Ankommen tạo Perfekt với sein, Futur II giữ trợ động từ đó.','ist','Cần nguyên mẫu sein ở cuối, ist là dạng hữu hạn.')
unit('Satzbau|Hauptsatz',31,'Câu trần thuật chính có động từ hữu hạn ở V2. Vị trí đầu là một thành phần, có thể gồm nhiều từ. Hôm nay tôi học: Heute lerne ich, không Heute ich lerne. Những phần động từ chưa chia nằm cuối trong khung câu.','Heute lerne ich Deutsch.','Hôm nay tôi học tiếng Đức.','Đếm thành phần, không đếm từ: Am frühen Morgen là một thành phần. Chủ ngữ không bắt buộc ở đầu câu.','Heute ___ ich Deutsch. (lernen)','lerne','lernen','Cần động từ đã chia theo ich.','ich lerne','Chủ ngữ ich đã có; đưa thêm ich làm sai khung câu.')
unit('Satzklammer',31,'Khung câu gồm động từ hữu hạn và phần động từ còn lại: Ich habe ... gelesen; ich muss ... arbeiten; ich rufe ... an. Mittelfeld nằm giữa. Ở mệnh đề phụ, cả cụm thường cuối, có ngoại lệ như Ersatzinfinitiv.','Ich habe den ganzen Abend gelesen.','Tôi đã đọc suốt buổi tối.','Ich habe gelesen den ganzen Abend có thể có Nachfeld nhấn đặc biệt, nhưng không phải mẫu trung hòa cần dùng ở bài nền tảng.','Ich rufe dich morgen ___. (anrufen)','an','anrufen','Rufe đã là phần chia, cuối câu chỉ cần tiền tố an.','angerufen','Partizip II không dùng sau rufe ở Präsens.')
unit('Hauptsatz Konnektoren ADUSO',9,'ADUSO: aber, denn, und, sondern, oder nối các thành phần/câu cùng bậc. Chúng không chiếm Vorfeld của câu tiếp theo. Sondern đính chính sau phủ định: nicht X, sondern Y. Denn nối lý do nhưng giữ trật tự câu chính.','Ich bleibe zu Hause, denn ich bin krank.','Tôi ở nhà vì tôi bị ốm.','Denn ich krank bin sai vị trí động từ; trật tự cuối dùng với weil. Sondern thường cần phủ định phần bị sửa.','Ich bin nicht müde, ___ hungrig.','sondern','denn','Denn đưa lý do, không đính chính từ müde sang hungrig.','oder','Oder đưa lựa chọn, không sửa lại thông tin bị phủ định.')
unit('Kausaler Konnektor denn',9,'Denn khi nối nguyên nhân giữ động từ hữu hạn ở V2 sau chủ ngữ/thành phần đầu câu thứ hai. Phân biệt denn tình thái trong câu hỏi: Was machst du denn? Hai chức năng không dùng chung một quy tắc vị trí.','Ich gehe früh, denn ich bin müde.','Tôi đi sớm vì tôi mệt.','Không đặt bin cuối như weil. Denn là liên từ đẳng lập nên không đẩy chủ ngữ xuống sau động từ.','Ich bleibe, denn ich ___ Zeit. (haben)','habe','haben','Ich cần habe ở V2.','Zeit habe','Zeit đã có sau chỗ trống; denn không yêu cầu động từ cuối.')
unit('Nebensatz',18,'Mệnh đề phụ với weil/dass/wenn thường đặt động từ đã chia cuối. Nếu cả mệnh đề phụ đứng đầu, nó chiếm Vorfeld của câu chính: Weil es regnet, bleibe ich hier. Mệnh đề phụ vẫn có chủ ngữ riêng nếu cấu trúc yêu cầu.','Ich bleibe hier, weil es regnet.','Tôi ở lại đây vì trời mưa.','Weil es regnet, ich bleibe hier sai V2 của câu chính; cần bleibe ich. Không áp cấu trúc câu hỏi cho mọi câu phụ.','Ich weiß, dass er heute ___. (kommen)','kommt','kommen','Er cần kommt, dù động từ nằm cuối.','kommt er','Chủ ngữ er đã có; không đảo theo mẫu câu hỏi.')
unit('Konjunktionen',18,'Liên từ đẳng lập (und/aber/denn) giữ câu chính; liên từ phụ thuộc (weil/dass/wenn) tạo mệnh đề động từ cuối. Trạng từ nối như deshalb chiếm Vorfeld và đẩy động từ lên ngay sau. Phải phân loại trước khi nối câu.','Es regnet, aber wir gehen spazieren.','Trời mưa nhưng chúng tôi vẫn đi dạo.','Aber không cùng mẫu với obwohl; deshalb không cùng mẫu với weil. Giữ nghĩa và trật tự tương ứng.','Ich bleibe zu Hause, ___ ich krank bin.','weil','denn','Denn yêu cầu ich bin krank, không phải bin cuối.','deshalb','Deshalb yêu cầu trật tự câu chính V2 và quan hệ nối khác.')
unit('Konjunktionaladverbien',52,'Deshalb/trotzdem/danach/jedoch có thể nối ý như trạng từ. Khi đứng đầu câu, chúng chiếm Vorfeld nên động từ theo ngay: Deshalb bleibe ich. Chúng cũng có thể ở Mittelfeld: Ich bleibe deshalb. Không giống denn/und.','Es regnet; trotzdem gehen wir hinaus.','Trời mưa; dù vậy chúng tôi ra ngoài.','Trotzdem wir gehen ... sai V2. Nếu dùng obwohl, phải cấu trúc lại thành mệnh đề phụ.','Es regnet; deshalb ___ ich hier. (bleiben)','bleibe','ich bleibe','Deshalb chiếm Vorfeld; động từ đứng trước chủ ngữ.','bleiben','Ich cần dạng bleibe.')
unit('Deshalb|Daher',52,'Deshalb/daher nối nguyên nhân với kết quả: Ich bin krank; deshalb bleibe ich zu Hause. Khi đứng đầu, theo sau bằng V2. Daher còn có thể chỉ nguồn xuất phát trong nghĩa khác; ở bài này tập trung liên kết lập luận.','Der Zug fällt aus; daher nehmen wir den Bus.','Tàu bị hủy; vì vậy chúng tôi đi xe buýt.','Không viết daher wir nehmen trong câu chính. Phân biệt kết quả với nhượng bộ trotzdem.','Ich bin krank; deshalb ___ ich zu Hause. (bleiben)','bleibe','ich bleibe','Cần V2 sau deshalb, không thêm chủ ngữ vào chỗ trống.','bleiben','Ich cần bleibe, không phải nguyên mẫu.')
unit('Trotzdem',55,'Trotzdem nêu sự việc vẫn xảy ra trái kỳ vọng từ điều vừa nói. Đầu câu: Trotzdem gehe ich. Có thể chuyển từ obwohl nhưng phải đổi cấu trúc: Obwohl es regnet, gehe ich → Es regnet; trotzdem gehe ich.','Es ist kalt; trotzdem gehen wir schwimmen.','Trời lạnh; dù vậy chúng tôi đi bơi.','Trotzdem không đồng nghĩa deshalb: một cái trái kỳ vọng, một cái kết quả do nguyên nhân.','Es regnet; ___ gehe ich spazieren. (dù vậy)','trotzdem','deshalb','Deshalb sẽ biến mưa thành lý do đi dạo, không giữ quan hệ nhượng bộ yêu cầu.','weil','Weil cần mệnh đề phụ, không đi với gehe ich như mẫu này.')
unit('Jedoch',55,'Jedoch biểu thị đối lập, có thể đứng đầu hoặc trong câu: Jedoch fehlt die Zeit / Die Zeit fehlt jedoch. Đầu câu nó thường chiếm Vorfeld; không xử lý như aber luôn nằm ngoài trường câu. Chọn vị trí theo nhịp thông tin.','Der Plan ist gut; jedoch fehlt uns das Geld.','Kế hoạch hay; tuy nhiên chúng tôi thiếu tiền.','Jedoch uns fehlt das Geld sai V2 nếu jedoch đứng đầu trong mẫu này.','Der Plan ist gut; jedoch ___ das Geld. (fehlen)','fehlt','fehlen','Chủ ngữ das Geld số ít cần fehlt.','das Geld fehlt','Chủ ngữ đã xuất hiện sau chỗ trống; jedoch cần động từ ngay sau.')
unit('Nämlich',52,'Nämlich bổ sung lý do/giải thích cho phát ngôn trước, thường ở Mittelfeld: Ich bin nämlich krank. Không dùng nó đầu câu như deshalb trong mẫu nền tảng. Không đồng nhất với nämlich nghĩa cụ thể là trong danh sách giải thích.','Ich komme nicht; ich bin nämlich krank.','Tôi không đến; vì tôi bị ốm.','Nämlich bin ich krank không phải trật tự trung hòa diễn đạt lý do. Đặt sau động từ/chủ ngữ theo trường câu.','Ich komme nicht; ich ___ nämlich krank. (sein)','bin','nämlich bin','Nämlich đã có sau chỗ trống; không lặp và đưa nó lên đầu.','ist','Ich cần bin.')
unit('Kausale Konjunktion weil|Kausalsatz',52,'Weil/da mở mệnh đề lý do với động từ cuối. Mệnh đề lý do đứng đầu thì câu chính bắt đầu bằng động từ: Weil ich krank bin, bleibe ich. Da thường nêu lý do được xem như đã biết; đây là khác biệt dụng học, không phải cấm hoán đổi mọi nơi.','Weil ich krank bin, bleibe ich zu Hause.','Vì bị ốm, tôi ở nhà.','Trong viết chuẩn ưu tiên weil + động từ cuối; weil + V2 tồn tại trong hội thoại với chức năng riêng, không dùng làm mẫu thi viết.','Ich bleibe, weil ich Zeit ___. (haben)','habe','habe ich','Chủ ngữ ich đã có, không đảo/lặp ở cuối mệnh đề.','haben','Ich cần habe.')
unit('Kausale Präpositionen',57,'Wegen/aufgrund + Genitiv nén nguyên nhân thành danh ngữ; aus có thể chỉ động cơ, vor chỉ phản ứng: aus Angst schweigen, vor Angst zittern. Không thay tất cả vì bằng một giới từ duy nhất. Khi chuyển từ weil, giữ tác thể và ý nghĩa.','Wegen des Regens bleiben wir zu Hause.','Vì mưa, chúng tôi ở nhà.','Wegen der Regen sai mạo từ và thiếu đuôi: der Regen → des Regens. Dativ khẩu ngữ không phải mẫu viết ưu tiên.','Aufgrund ___ Sturms fällt der Flug aus.','des','den','Aufgrund ở mẫu viết này dùng Genitiv.','das','Sturm giống đực, Genitiv là des Sturms.')
unit('Konjunktion dass|Das oder dass?',62,'Dass mở mệnh đề nội dung, động từ cuối; das là mạo từ hoặc đại từ chỉ định/quan hệ. Thử thay bằng dieses/jenes/welches khi phù hợp: làm được thường là das. Phép thử cần cả câu và đúng chức năng, không phải đổi tự do ở mọi vị trí.','Ich weiß, dass das richtig ist.','Tôi biết rằng điều đó đúng.','Dấu phẩy không tự quyết định das/dass: Das Buch, das ich lese có das quan hệ.','Ich hoffe, ___ du kommst.','dass','das','Ở đây cần liên từ nội dung, không có danh từ tiền ngữ cho đại từ quan hệ.','denn','Denn yêu cầu câu chính và nghĩa nguyên nhân, không phải nội dung hy vọng.')
unit('Konditionale Konjunktion falls|Konditionalsatz',56,'Falls/wenn/sofern mở điều kiện với động từ cuối. Điều kiện có thể thực tế hoặc giả định; chọn Indikativ/Konjunktiv theo ý. Nâng cao có thể đảo không liên từ: Sollte es regnen, bleiben wir. Không dùng würde mọi khi thấy wenn.','Falls es regnet, bleiben wir zu Hause.','Nếu trời mưa, chúng tôi ở nhà.','Falls es regnet, wir bleiben ... sai V2 câu chính. Falls không có nghĩa khi nào trong mọi ngữ cảnh như wenn thời gian.','Falls du Hilfe ___, ruf mich an. (brauchen)','brauchst','braucht','Du cần brauchst.','brauchst du','Du đã có ở đầu mệnh đề; không đảo như câu hỏi.')
unit('Finale Konjunktion damit|Finalsatz',44,'Damit + mệnh đề chia động từ nói mục đích; um ... zu thường dùng khi chủ thể hành động được hiểu trùng nhau. Không chuyển máy móc nếu hai chủ thể khác: Ich helfe dir, damit du fertig wirst. Mục đích chưa đảm bảo kết quả đã xảy ra.','Ich spreche langsam, damit du mich verstehst.','Tôi nói chậm để bạn hiểu tôi.','Um du mich zu verstehen sai vì có chủ ngữ khác trong cụm nguyên mẫu. Dùng damit cho hai chủ thể rõ ràng.','Ich helfe dir, ___ du fertig wirst.','damit','weil','Weil nêu lý do có sẵn, không biểu thị mục đích yêu cầu.','obwohl','Obwohl biểu thị nhượng bộ, khác nghĩa.')
unit('Konsekutive Konjunktion sodass|Sodass oder so dass',59,'Sodass/so dass đều có thể viết khi là liên từ kết quả. Phân biệt so ... dass khi so bổ nghĩa một tính từ/trạng từ phía trước: so laut, dass ... . Kết quả không đồng nghĩa mục đích damit. Động từ hữu hạn cuối mệnh đề phụ.','Es war so laut, dass ich nichts hörte.','Ồn đến mức tôi không nghe được gì.','Trong so laut, dass, không kéo so sang liên từ rồi bỏ yếu tố mức độ ở tính từ. Cả sodass và so dass hợp lệ khi dùng như liên từ kết quả độc lập.','Es regnete stark, ___ die Straßen überflutet wurden. (một từ)','sodass','damit','Damit sẽ biểu thị mục đích của mưa, không phải hệ quả.','obwohl','Obwohl diễn đạt nhượng bộ, trái quan hệ kết quả.')
unit('Konzessive Konjunktion obwohl|Konzessivsatz',55,'Obwohl/trotzdem nói trái kỳ vọng; obwohl mở mệnh đề phụ, trotzdem là trạng từ nối ở câu chính. Dùng obwohl cho sự việc được nêu như thực; auch wenn có thể thực hoặc giả định theo ngữ cảnh. Không đồng nhất dù với mọi wenn.','Obwohl er müde ist, arbeitet er weiter.','Dù mệt, anh ấy vẫn tiếp tục làm việc.','Obwohl er ist müde sai vị trí động từ. Câu chính sau mệnh đề đầu bắt đầu arbeitet er.','___ er müde ist, arbeitet er weiter. (mặc dù)','Obwohl','Weil','Weil biến mệt thành lý do tiếp tục, không giữ nhượng bộ.','Damit','Damit chỉ mục đích, khác quan hệ đang hỏi.')
unit('Modale Konjunktion indem|Modalsatz',60,'Indem diễn đạt cách làm để đạt một điều gì; dadurch, dass có thể nhấn phương thức/quan hệ tạo kết quả. Chọn chủ thể và nghĩa rõ, không chỉ nhìn có hai hành động đồng thời. Nicht indem khi chỉ muốn nói thời gian: dùng während trong ý đồng thời thuần túy.','Sie lernt, indem sie Beispiele analysiert.','Cô ấy học bằng cách phân tích ví dụ.','Indem không đồng nghĩa als/before; phải có quan hệ phương thức, không chỉ hai việc tình cờ xảy ra.','Sie spart Geld, ___ sie selbst kocht. (bằng cách)','indem','obwohl','Obwohl là nhượng bộ, không nêu cách tiết kiệm.','bevor','Bevor là trước khi, đổi quan hệ nghĩa.')
unit('Dadurch dass',60,'Dadurch, dass nối một cơ chế hoặc hoàn cảnh dẫn đến kết quả. Có thể tách dadurch ở câu chính: Dadurch spart sie Geld, dass ... nhưng thường viết tự nhiên Sie spart dadurch Geld, dass ... . Dấu phẩy đứng trước dass khi dadurch thuộc câu chính.','Sie spart dadurch Geld, dass sie selbst kocht.','Cô ấy tiết kiệm bằng việc tự nấu ăn.','Nicht dadurch weil: cấu trúc tương quan này dùng dass. Đừng dùng chỉ để thay một khi thời gian.','Sie spart dadurch Geld, ___ sie selbst kocht.','dass','weil','Mẫu tương quan dadurch ... dass yêu cầu dass.','obwohl','Obwohl không hoàn thành cấu trúc phương thức tương quan.')
unit('Ohne dass',44,'Ohne dass nói sự việc không xảy ra đi cùng hành động chính, dùng được với chủ ngữ khác. Ohne ... zu thường có chủ thể được hiểu từ mệnh đề chính. Không hiểu thành mệnh lệnh cấm; đây là quan hệ thiếu/không có hành động kèm theo.','Er ging, ohne dass ich es bemerkte.','Anh ấy đi mà tôi không nhận ra.','Er ging, ohne ich es zu bemerken sai khi hai chủ thể khác nhau; dùng ohne dass + động từ chia.','Er ging, ohne ___ ich es bemerkte.','dass','zu','Zu không đứng trước một mệnh đề có chủ ngữ ich như vậy.','damit','Damit chỉ mục đích, không phải cấu trúc ohne dass.')
unit('Temporalsatz',52,'Mệnh đề thời gian dùng als/wenn/bevor/nachdem/während/bis/seit(dem) theo quan hệ. Als thường cho sự kiện một lần trong quá khứ; wenn cho lặp lại hoặc hiện tại/tương lai. Bevor/nachdem chỉ trước–sau theo hành động câu chính.','Als ich ankam, wartete sie schon.','Khi tôi đến, cô ấy đã chờ sẵn.','Không chọn liên từ chỉ từ bản dịch khi. Hãy hỏi một lần quá khứ, lặp lại, trước–sau hay đồng thời.','___ ich gestern ankam, war es dunkel.','Als','Wenn','Câu này nói một lần cụ thể hôm qua, mẫu chuẩn dùng als.','Bevor','Bevor có nghĩa trước khi, không phải khi đến đúng mốc.')
unit('Temporale Konjunktion als',34,'Als dùng cho sự kiện một lần hoặc một giai đoạn được nhìn như một thời kỳ trong quá khứ: Als ich ein Kind war. Không dùng als thời gian cho một điều kiện tương lai. Phân biệt als so sánh và als thời gian theo cấu trúc.','Als ich ein Kind war, wohnte ich in Bonn.','Khi còn nhỏ, tôi sống ở Bonn.','Wenn ich ein Kind war không phải mẫu kể một giai đoạn tuổi thơ trung hòa; dùng als. Lặp lại mỗi lần có thể dùng immer wenn.','___ ich gestern anrief, war niemand da.','Als','Wenn','Một cuộc gọi xác định hôm qua dùng als.','Während','Während nhấn đồng thời trong một khoảng, khác mốc gọi đơn lẻ đang hỏi.')
unit('Temporale Konjunktion wenn',34,'Wenn thời gian dùng cho lặp lại hoặc sự việc hiện tại/tương lai. Wenn điều kiện dùng nếu. Ngữ cảnh quyết định cách hiểu: Wenn ich Zeit habe, lese ich. Khi muốn tách rõ điều kiện có thể dùng falls.','Immer wenn ich frei habe, lese ich.','Mỗi khi rảnh, tôi đọc sách.','Không dùng als cho việc lặp lại được đánh dấu immer. Trong câu phụ, habe vẫn đứng cuối.','Immer ___ es regnet, nehme ich einen Schirm mit.','wenn','als','Als thời gian không dùng cho chuỗi mỗi lần lặp như mẫu này.','nachdem','Nachdem nêu sau khi hoàn tất, không giữ nghĩa mỗi khi.')
unit('Temporale Konjunktion bis',52,'Bis mở mệnh đề chỉ điểm kết thúc một khoảng kéo dài: Warte, bis ich komme. Không thêm khi nào trong cùng cấu trúc. Unterscheide bis (đến khi) với seitdem (từ khi) và bevor (trước khi).','Warte hier, bis ich zurückkomme.','Hãy đợi ở đây cho đến khi tôi quay lại.','Bis ich komme, warte hier có thể hợp ngữ pháp nhưng cần kiểm tra trọng tâm; lỗi căn bản là bis ich komme zurück khi zurückkommen phải liền ở cuối.','Warte, ___ ich zurückkomme. (cho đến khi)','bis','seitdem','Seitdem đánh dấu điểm bắt đầu, không phải kết thúc chờ.','obwohl','Obwohl là nhượng bộ, không phải mốc kết thúc.')
unit('Temporale Konjunktion bevor',52,'Bevor mở hành động xảy ra sau hành động câu chính: Ich lese den Vertrag, bevor ich unterschreibe. Không suy thì chỉ từ bevor; cả hai mệnh đề có thể Präsens khi nói kế hoạch/thói quen. Dấu phẩy phân cách câu phụ.','Lies den Vertrag, bevor du unterschreibst.','Đọc hợp đồng trước khi ký.','Bevor đối lập nachdem trong thứ tự. Đừng đảo hành động khi chuyển thành vor der Unterschrift.','Lies alles, ___ du unterschreibst. (trước khi)','bevor','nachdem','Nachdem sẽ đặt việc đọc sau khi ký, đảo quan hệ.','seitdem','Seitdem là từ khi, không biểu thị trước khi.')
unit('Temporale Konjunktion nachdem',52,'Nachdem diễn đạt sự kiện câu phụ trước câu chính. Khi kể quá khứ thường Plusquamperfekt + Präteritum: Nachdem ich gegessen hatte, ging ich. Không phải mọi nachdem bắt buộc cặp đó: Präsens/Perfekt dùng khi mốc khác.','Nachdem ich gegessen hatte, ging ich spazieren.','Ăn xong rồi tôi đi dạo.','Nachdem ich gegessen hatte chỉ hành động trước; không thay hatte bằng würde để nói quá khứ thực.','Nachdem ich gegessen ___, ging ich hinaus. (haben)','hatte','hätte','Hätte là giả định, không phải Plusquamperfekt thực tế ở đây.','haben','Cần trợ động từ hữu hạn theo ich, không phải nguyên mẫu.')
unit('Temporale Konjunktion während',52,'Während + mệnh đề: trong khi/đang lúc, động từ cuối. Während + Genitiv là giới từ. Ngoài đồng thời, während còn đối chiếu hai sự việc tương phản; dùng ngữ cảnh để chọn nghĩa chứ không luôn dịch trong lúc.','Während ich koche, hört sie Musik.','Trong lúc tôi nấu ăn, cô ấy nghe nhạc.','Während des Kochens là danh ngữ; während ich koche là mệnh đề. Không ghép ich với danh từ hóa như một cụm Genitiv.','Während ich ___, hört sie Musik. (kochen)','koche','kochen','Ich cần koche ở cuối câu phụ.','koche ich','Chủ ngữ đã ở đầu câu phụ, không lặp như câu hỏi.')
unit('Temporale Konjunktion seit|Seitdem oder seit dem',34,'Seit/seitdem + mệnh đề dùng động từ cuối: seitdem ich hier wohne. Seit dem + danh ngữ là giới từ và mạo từ Dativ: seit dem Umzug. Seitdem cũng có thể là trạng từ độc lập: Seitdem wohne ich hier.','Seit dem Umzug fahre ich mit dem Bus.','Từ khi chuyển nhà, tôi đi xe buýt.','Không viết seitdem Umzug khi sau đó là danh từ cần mạo từ. Ngược lại seit dem ich hier wohne sai nếu cần liên từ.','___ ich hier wohne, fahre ich mit dem Bus. (một từ)','Seitdem','Seit dem','Sau đó có mệnh đề ich ... wohne nên cần liên từ một từ.','Nach dem','Nach dem cần danh ngữ và diễn đạt sau, không mở mệnh đề này.')
unit('Negation: Verneinung im Deutschen',8,'Kein phủ định danh ngữ với ein hoặc không mạo từ: kein Auto, keine Zeit. Nicht phủ định tính từ, động từ, giới từ hoặc thành phần cụ thể: nicht müde, nicht in Berlin. Vị trí nicht phụ thuộc phạm vi phủ định; không có quy tắc luôn đứng cuối.','Ich habe kein Auto.','Tôi không có ô tô.','Nicht ein Auto có thể đối chiếu một chiếc với số khác, nhưng phủ định tồn tại trung hòa là kein Auto.','Ich bin ___ müde.','nicht','kein','Kein không đứng trực tiếp phủ định tính từ vị ngữ müde.','keine','Keine là từ hạn định danh từ, không phù hợp ở đây.')
unit('Reflexive Verben|Reflexivpronomen',23,'Động từ phản thân dùng đại từ cùng chủ thể: Ich erinnere mich. Akkusativ mich/dich/sich/uns/euch/sich; Dativ mir/dir/sich... khi cấu trúc yêu cầu: Ich wasche mir die Hände. Không tự thêm sich vào mọi động từ theo bản dịch tự mình.','Ich wasche mir die Hände.','Tôi rửa tay.','Die Hände đã là Akkusativ, người sở hữu/được tác động dùng Dativ mir. Ich wasche mich là rửa người mình, nghĩa khác.','Ich wasche ___ die Hände. (ich)','mir','mich','Akkusativ đã do die Hände đảm nhiệm; dùng Dativ phản thân mir.','sich','Sich không dùng cho ngôi ich.')
unit('Reflexive Verben mit Präpositionen',39,'Học cả ba phần: sich + động từ + giới từ/cách. Sich freuen auf + Akkusativ cho mong chờ; sich freuen über + Akkusativ cho vui về việc đang/đã có; sich beschäftigen mit + Dativ. Không đổi giới từ tùy bản dịch.','Ich freue mich auf den Urlaub.','Tôi mong chờ kỳ nghỉ.','Ich freue mir sai vì sich freuen dùng Akkusativ phản thân. Auf/über còn thay đổi điểm nhìn thời gian của niềm vui.','Ich beschäftige mich ___ dem Thema.','mit','auf','Sich beschäftigen kết hợp mit + Dativ, không auf.','für','Für dùng với sich interessieren trong mẫu khác, không phải beschäftigen.')
unit('Verben mit Präpositionen',39,'Giới từ gắn với nghĩa động từ: warten auf + Akkusativ, teilnehmen an + Dativ, sprechen über + Akkusativ. Với vật có thể hỏi worauf/woran/worüber; với người dùng auf wen/mit wem. Không suy cách từ không gian trong các kết hợp trừu tượng.','Ich warte auf den Bus.','Tôi đợi xe buýt.','Warten für den Bus là dịch từng chữ sai kết hợp. Worauf wartest du? hỏi vật; Auf wen wartest du? hỏi người.','Ich nehme ___ dem Kurs teil.','an','auf','Teilnehmen kết hợp an + Dativ.','für','Für không thuộc kết hợp teilnehmen ở nghĩa tham gia.')
unit('Präpositionalpronomen',28,'Da(r)+giới từ thay cho vật/sự việc: darauf, damit, daran; wo(r)+giới từ hỏi: worauf, womit. Thêm r trước nguyên âm: daran. Với người, dùng giới từ + đại từ người: mit ihm, không damit khi nói với anh ấy.','Ich warte darauf.','Tôi đang đợi điều đó.','Damit không thay mit ihm nếu đối tượng là người. Phải giữ giới từ mà động từ gốc đòi.','Warten auf etwas → Ich warte ___.','darauf','damit','Damit thay mit, không giữ auf của warten auf.','daran','Daran thay an, không phải auf.')
unit('Pronomen es',62,'Es có thể thay danh từ trung, giữ vai trò chủ ngữ giả thời tiết, chỉ cả sự việc hoặc giữ chỗ Vorfeld. Không phải mọi es đều bỏ được. Es regnet có chủ ngữ hình thức bắt buộc; Es wird getanzt → Heute wird getanzt thì es chỉ giữ chỗ và biến mất.','Heute regnet es.','Hôm nay trời mưa.','Không bỏ es của regnen khi có heute: Heute regnet thiếu chủ ngữ. Nhưng Heute wird es getanzt sai khi es chỉ giữ chỗ bị động không chủ ngữ.','Heute regnet ___.','es','nichts','Nichts nghĩa không có gì, không phải chủ ngữ hình thức của mưa.','man','Man sẽ chỉ người, không phải chủ ngữ thời tiết.')
unit('N-Deklination',25,'Danh từ yếu giống đực thêm -(e)n ở Akkusativ/Dativ/Genitiv số ít: der Student, den Studenten, dem Studenten, des Studenten. Nominativ giữ dạng gốc. Nhóm hỗn hợp có thêm -s ở Genitiv: der Name → des Namens. Không áp cho mọi danh từ giống đực.','Ich spreche mit dem Studenten.','Tôi nói chuyện với sinh viên nam.', 'Mit dem Student thiếu -en. Số nhiều cũng Studenten nhưng phải xem mạo từ và động từ để xác định số.','Ich sehe den ___. (Student)','Studenten','Student','Student yếu cần -en ở Akkusativ số ít.','Students','-s không phải dạng Akkusativ của danh từ yếu này.')
unit('Indefinitpronomen',11,'Jemand/niemand chỉ người không xác định, etwas/nichts chỉ vật/sự việc. Einer/keiner có thể thay danh ngữ và phải biến cách. Nicht alle không đồng nghĩa niemand: không phải tất cả vẫn có thể một số. Chọn theo người/vật và phạm vi phủ định.','Ich habe niemanden gesehen.','Tôi không thấy ai.','Không dùng nichts khi muốn nói không thấy người nào; nichts là không có gì. Jemand có biến thể đuôi tùy cách và văn phong.','Ich habe ___ gesehen. (không ai; dạng có đuôi)','niemanden','nichts','Nichts chỉ sự vật, không khớp không ai.','keine','Keine cần giống/số/danh ngữ tham chiếu khác, không phải dạng người chung ở đây.')
unit('Irgendwie, irgendwo, irgendwann',11,'Irgendwie: bằng cách nào đó/không rõ vì sao; irgendwo: ở đâu đó; irgendwann: lúc nào đó. Dùng để biểu thị không xác định, không tự mang nghĩa phủ định. Hướng đi dùng irgendwohin, không chỉ irgendwo khi cần nhấn đích.','Wir treffen uns irgendwann nächste Woche.','Chúng ta gặp nhau lúc nào đó vào tuần sau.','Không dùng irgendwo cho thời điểm. Irgendwie có thể làm lời đánh giá mơ hồ, không chỉ cách thức vật lý.','Wir treffen uns ___ nächste Woche. (lúc nào đó)','irgendwann','irgendwo','Irgendwo nói địa điểm, không phải thời gian.','irgendwie','Irgendwie nói cách thức/đánh giá mơ hồ, không xác định lúc nào.')
unit('Relativpronomen der, die, das|Relativsatz',26,'Đại từ quan hệ nhận giống/số từ danh từ tiền ngữ, nhưng cách từ vai trò trong mệnh đề quan hệ. Der Mann, den ich sehe: Mann đực số ít nhưng den vì là Akkusativ của sehe. Giới từ đứng trước: mit dem ich spreche. Động từ cuối.','Das ist der Mann, dem ich helfe.','Đó là người đàn ông mà tôi giúp.','Không chọn der chỉ vì Mann làm chủ ngữ câu chính; trong câu phụ helfen đòi Dativ nên dem.','Der Mann, ___ ich helfe, ist nett.','dem','den','Helfen cần Dativ, không phải Akkusativ.','der','Der là Nominativ, không đúng vai trò trong mệnh đề quan hệ này.')
unit('mit was und wo',45,'Trong mệnh đề quan hệ, was thường theo alles/etwas/nichts hoặc một ý cả câu: Alles, was ...; wo dùng nơi chốn theo ngữ cảnh: der Ort, wo ... . Trong văn viết chính xác có thể dùng giới từ + dem/der: die Stadt, in der ... . Không thay mọi đại từ quan hệ bằng wo.','Alles, was ich weiß, steht hier.','Tất cả những gì tôi biết nằm ở đây.','Nicht der Mann, was ... khi nói người; dùng der/den/dem theo chức năng. Was không phải đại từ quan hệ chung cho mọi danh từ.','Alles, ___ ich brauche, ist hier.','was','wer','Wer chỉ người, không nối alles ở mẫu này.','wo','Wo chỉ nơi chốn, không làm tân ngữ của brauche.')
unit('Indirekte Frage formulieren',18,'Câu hỏi gián tiếp là mệnh đề phụ: Ich weiß nicht, wo er wohnt. Câu hỏi có/không dùng ob: Weißt du, ob er kommt? Phân biệt wenn điều kiện với ob có hay không. Động từ hữu hạn cuối, không giữ đảo câu hỏi trực tiếp.','Weißt du, wann der Zug abfährt?','Bạn biết khi nào tàu khởi hành không?', 'Wann fährt der Zug ab? là trực tiếp; nhúng sau Weißt du cần wann der Zug abfährt.','Ich weiß nicht, ___ er kommt. (có hay không)','ob','wenn','Wenn chỉ điều kiện/thời gian, không phải câu hỏi có/không ở đây.','denn','Denn là liên từ lý do hoặc tiểu từ, không tạo câu hỏi gián tiếp này.')
unit('Indirekte Rede',46,'Lời gián tiếp tách nguồn phát ngôn khỏi người thuật. Konjunktiv I thường dùng trong báo chí; nếu trùng Indikativ, dùng Konjunktiv II hoặc würde khi cần rõ. Đổi ngôi và mốc theo điểm nhìn mới nhưng không tự đổi nội dung/lập trường.','Sie sagt, sie sei krank.','Cô ấy nói rằng cô ấy bị ốm.','Sei không tự có nghĩa người nói dối. Đổi thành wäre có thể là dạng thay thế hoặc sắc thái khác tùy ngữ cảnh; không coi luôn là quá khứ.','Er sagt, er ___ krank. (sein; Konjunktiv I)','sei','ist','Ist là Indikativ, không phải dạng Konjunktiv I đang yêu cầu.','war','War là Indikativ Präteritum, thay cả thức và mốc.')
unit('Konjunktiv 1',37,'Konjunktiv I chủ yếu dùng thuật lại lời trong văn trang trọng: er komme, er habe, er sei. Tạo từ gốc nguyên mẫu với -e/-est/-e/-en/-et/-en, riêng sein có sei. Dạng trùng Indikativ có thể cần thay thế để rõ nguồn lời.','Der Zeuge sagt, er habe nichts gesehen.','Nhân chứng nói mình không thấy gì.','Habe không phải hat; với er, Konjunktiv I bỏ -t. Không thay mọi động từ bằng würde nếu Konjunktiv I đã rõ và văn phong phù hợp.','Er sagt, er ___ Zeit. (haben; Konjunktiv I)','habe','hat','Hat là Indikativ.','hatte','Hatte là Indikativ quá khứ, không phải Konjunktiv I.')
unit('Konjunktiv 1 der Vergangenheit',46,'Lời gián tiếp quá khứ: habe/sei + Partizip II. Dùng habe gearbeitet, sei gekommen. Konjunktiv I không có ba dạng quá khứ khác nhau tương ứng toàn bộ thì Indikativ; diễn đạt quan hệ bằng trợ động từ và ngữ cảnh.','Sie berichtet, sie sei früh angekommen.','Cô ấy thuật lại rằng mình đã đến sớm.','Ankommen dùng sein; không tạo habe angekommen. Không dùng war như một Konjunktiv I chỉ vì chuyện đã qua.','Er sagt, er ___ den Brief gelesen. (Konjunktiv I)','habe','hätte','Hätte là Konjunktiv II, không phải dạng đang yêu cầu.','hatte','Hatte là Indikativ Plusquamperfekt khi kết hợp Partizip, khác thức.')
unit('Hätte, wäre, würde|Konjunktiv 2 der Gegenwart',29,'Konjunktiv II diễn đạt giả định phi thực, ước muốn, lời khuyên hoặc lịch sự ở hiện tại/tương lai: hätte Zeit, wäre reich, würde reisen. Không hiểu hätte/wäre tự động là quá khứ. Sein/haben/Modalverb thường dùng dạng riêng thay vì würde + Infinitiv.','Wenn ich Zeit hätte, würde ich reisen.','Nếu có thời gian, tôi sẽ đi du lịch.','Wenn ich Zeit hatte nói quá khứ thực/lặp, khác giả định hätte. Würde đã chia nên động từ còn lại giữ nguyên mẫu.','Wenn ich Zeit ___, würde ich reisen. (haben; giả định)','hätte','hatte','Hatte là quá khứ Indikativ, không phải giả định.','habe','Habe nói điều kiện thực tế hiện tại, không đúng yêu cầu phi thực.')
unit('Konjunktiv 2 der Vergangenheit',42,'Giả định/tiếc nuối quá khứ: hätte/wäre + Partizip II. Nếu có Modalverb và nguyên mẫu bổ sung: hätte arbeiten müssen. Phân biệt wäre gekommen (đã đến trong giả định) với würde kommen (sẽ/đến ở hiện tại–tương lai).','Wenn ich Zeit gehabt hätte, wäre ich gekommen.','Nếu khi đó có thời gian, tôi đã đến.', 'Không dùng hätte gekommen vì kommen ở nghĩa đến dùng sein. Tình huống đã qua cần cụm Perfekt giả định, không chỉ würde kommen.','Ich ___ gern gekommen. (giả định quá khứ)','wäre','hätte','Kommen dùng sein nên cần wäre.','würde','Würde gekommen thiếu trợ động từ và không tạo Konjunktiv II quá khứ đúng.')
unit('Vergleichssätze mit als ob',42,'Als ob mở so sánh giả định: Er tut so, als ob er alles wüsste. Konjunktiv II thường thể hiện khoảng cách với thực tế. Có thể bỏ ob và đảo: als wüsste er alles. Không giữ đồng thời ob rồi áp trật tự đảo đó.','Er tut so, als ob er alles wüsste.','Anh ấy làm như mình biết hết mọi thứ.','Als ob wüsste er alles sai trật tự cho mẫu có ob; nếu bỏ ob thì als wüsste er alles hợp lệ.','Er tut so, als ob er alles ___. (wissen; KII)','wüsste','wusste','Wusste là Präteritum, không phải Konjunktiv II được yêu cầu.','wissen','Cần động từ đã chia theo er.')
unit('Vorgangspassiv|Passiv Präsens',19,'Werden đã chia + Partizip II đặt quá trình/hành động vào trung tâm. Akkusativ của chủ động có thể thành chủ ngữ; Dativ giữ Dativ. Người thực hiện có thể nêu với von. Không phải câu nào cũng chuyển bị động tự nhiên.','Der Brief wird geschrieben.','Bức thư đang được viết.','Der Brief ist geschrieben nói trạng thái đã xong, khác wird geschrieben nhấn quá trình. Chọn theo điều muốn nói.','Der Brief ___ geschrieben. (bị động Präsens)','wird','ist','Ist + Partizip ở đây là Zustandspassiv, không phải quá trình đang yêu cầu.','hat','Hat viết Perfekt chủ động cần chủ thể viết, không hợp chủ ngữ Brief ở nghĩa này.')
unit('Passiv Präteritum',47,'Bị động quá trình ở Präteritum: wurde/wurden + Partizip II. Chủ ngữ số ít dùng wurde, số nhiều wurden; thời quá khứ ở trợ động từ. Không nhầm wurde không Umlaut với würde giả định.','Der Brief wurde gestern geschrieben.','Bức thư đã được viết hôm qua.','Würde geschrieben là giả định, không phải quá khứ thực. Không thêm ge vào động từ không có dạng đó.','Der Brief ___ gestern geschrieben. (Präteritum)','wurde','würde','Würde là Konjunktiv II, không phải quá khứ thực.','wurden','Brief số ít cần wurde.')
unit('Passiv Perfekt',47,'Perfekt bị động quá trình: ist/sind + Partizip II + worden. Worden không ge, khác geworden của werden nghĩa trở thành. Chủ ngữ quyết định ist/sind; quá trình được nêu như đã xảy ra.','Der Brief ist geschrieben worden.','Bức thư đã được viết.','Geschrieben geworden không phải Perfekt bị động chuẩn. Ist geschrieben một mình thường là trạng thái, không nêu rõ quá trình như ist ... worden.','Der Brief ist geschrieben ___.','worden','geworden','Geworden thuộc werden nghĩa trở thành, không phải trợ động từ bị động ở đây.','werden','Werden là nguyên mẫu, không tạo Perfekt bị động này.')
unit('Passiv mit Modalverben',47,'Modalverb đã chia + Partizip II + werden: Der Antrag muss geprüft werden. Partizip nêu hành động, werden tạo bị động, Modalverb nêu nghĩa vụ/khả năng. Không bỏ werden vì làm mất cấu trúc bị động.','Der Antrag muss geprüft werden.','Đơn cần được kiểm tra.','Der Antrag muss prüfen nghĩa đơn phải tự kiểm tra, sai vai trò. Phải giữ Partizip và werden.','Der Antrag muss geprüft ___.','werden','sein','Sein đổi sang nghĩa trạng thái cần được duy trì/đã xong, không phải quá trình đang luyện.','worden','Worden thuộc Perfekt; sau muss cần nguyên mẫu werden.')
unit('Zustandspassiv',53,'Sein + Partizip II nhấn trạng thái kết quả: Die Tür ist geschlossen. Werden + Partizip II nhấn quá trình đóng. Không phải mọi sein + Partizip đều là bị động: Er ist angekommen là Perfekt chủ động. Phân biệt theo động từ và nghĩa.','Die Tür ist geschlossen.','Cửa đang ở trạng thái đóng.','Ist geschlossen không nói ai/bao giờ đã đóng nếu không có ngữ cảnh. Wird geschlossen là quá trình cửa được đóng.','Die Tür ___ geschlossen. (trạng thái hiện tại)','ist','wird','Wird nhấn quá trình, không phải trạng thái yêu cầu.','hat','Hat không tạo trạng thái bị động của Tür ở mẫu này.')
unit('Passiv Ersatzformen',21,'Một số dạng thay bị động: sich lassen + Infinitiv (khả năng), sein + zu + Infinitiv (cần/có thể), tính từ -bar (khả năng). Không hoán đổi mọi mẫu mà giữ nguyên nghĩa: ist zu prüfen thường nói nghĩa vụ, ist prüfbar nói có thể kiểm tra.','Das Problem lässt sich lösen.','Vấn đề này có thể giải quyết được.','Lässt sich lösen không phải ai đó tự cho phép mình giải quyết; ở đây là cách diễn đạt khả năng bị động.','Das Problem lässt sich ___. (lösen)','lösen','gelöst','Sau lassen cần nguyên mẫu không zu, không phải Partizip II.','zu lösen','Mẫu sich lassen không dùng zu trước nguyên mẫu.')
unit('Gerundiv',48,'Zu + Partizip I làm định ngữ mang nghĩa cần/phải/có thể được làm tùy ngữ cảnh: die zu prüfenden Anträge. Nó nhận đuôi tính từ, không phải zu + nguyên mẫu đứng độc lập. Động từ tách: die auszufüllenden Formulare.','Die zu prüfenden Anträge liegen hier.','Các đơn cần kiểm tra nằm ở đây.','Die zu prüfen Anträge thiếu Partizip I và đuôi. Phân biệt die prüfenden Personen chủ động với die zu prüfenden Personen bị động/nghĩa vụ.','Die zu ___ Anträge liegen hier. (prüfen; định ngữ)','prüfenden','prüfen','Cần Partizip I + đuôi -en, không phải nguyên mẫu.','geprüften','Geprüften nói đơn đã được kiểm tra, khác việc cần được kiểm tra.')
unit('Subjektive Bedeutung von Modalverben',61,'Modalverb có thể biểu thị mức chắc chắn hoặc nguồn tin: muss chắc hẳn, könnte có thể, dürfte có lẽ; soll nghe nói, will tự khẳng định. Với sự việc đã qua dùng Infinitiv Perfekt: muss gegangen sein, soll gearbeitet haben. Không gán tỷ lệ chắc chắn tuyệt đối.','Sie muss den Termin vergessen haben.','Hẳn cô ấy đã quên cuộc hẹn.','Musste den Termin vergessen dễ thành nghĩa đã buộc phải quên; để phỏng đoán việc quá khứ dùng muss ... vergessen haben.','Er kann nicht dort gewesen ___.','sein','haben','Gewesen thuộc sein; Infinitiv Perfekt là gewesen sein.','ist','Sau Modalverb cần nguyên mẫu, không phải động từ hữu hạn ist.')
unit('Nomen Verb Verbindungen',49,'Cụm động từ–danh từ có kết hợp cố định: eine Entscheidung treffen, Kritik üben, zur Verfügung stehen/stellen. Phân biệt hành động đưa vào với trạng thái: in Betrieb nehmen / in Betrieb sein. Không thay động từ chức năng tùy bản dịch làm.','Wir treffen morgen eine Entscheidung.','Ngày mai chúng tôi sẽ quyết định.','Eine Entscheidung machen là kết hợp thiếu tự nhiên trong nghĩa này; dùng treffen hoặc entscheiden.','Wir ___ eine Entscheidung. (treffen; Präsens)','treffen','machen','Kết hợp chuẩn đang học là eine Entscheidung treffen.','geben','Eine Entscheidung geben không phải kết hợp mang nghĩa quyết định ở đây.')
unit('TEKAMOLO',31,'Trật tự trung hòa của các trạng ngữ thường Zeit–Grund–Art–Ort: temporal, kausal, modal, lokal. Đây là định hướng, không là luật bất biến. Đại từ, tân ngữ, thông tin đã biết/mới và trọng âm có thể tạo trật tự khác. Không sửa một câu đúng chỉ vì không giống TEKAMOLO.','Ich fahre morgen wegen des Streiks mit dem Bus zur Arbeit.','Ngày mai vì đình công, tôi đi làm bằng xe buýt.','Morgen có thể đưa lên đầu: Morgen fahre ich ... . Câu vẫn V2; không áp TEKAMOLO ngoài phạm vi trạng ngữ một cách cơ học.','Trong câu mẫu, “mit dem Bus” biểu thị gì?','Cách thức/phương tiện','Nguyên nhân','Nguyên nhân ở câu mẫu là wegen des Streiks.','Thời gian','Thời gian ở câu mẫu là morgen.')
unit('Uhrzeit im Deutschen',7,'Giờ chính thức: 14:30 = vierzehn Uhr dreißig. Khẩu ngữ: halb drei = 2:30, không phải 3:30. Viertel nach/vor chỉ hơn/kém mười lăm phút; một số vùng có mẫu khác. Dùng um khi hẹn giờ cụ thể.','Der Kurs beginnt um halb drei.','Khóa học bắt đầu lúc hai giờ rưỡi.','Halb drei hướng đến giờ ba nên mới hai giờ rưỡi. Không dịch máy móc ba rưỡi.','Halb drei là mấy giờ?','2:30','3:30','Ba rưỡi là halb vier, không phải halb drei.','2:15','Hai giờ mười lăm là Viertel nach zwei trong mẫu phổ biến.')
unit('Modalpartikel|Partikel',31,'Tiểu từ không biến cách; chức năng có thể nhấn, giới hạn, mức độ hoặc thái độ. Doch/ja/denn/mal ở nghĩa tình thái thường trong Mittelfeld và không nhấn mạnh. Nur/sogar ở nghĩa nhấn có phạm vi riêng. Không dịch mỗi từ bằng một nghĩa Việt bất biến.','Kannst du mir mal helfen?','Bạn giúp mình một chút được không?', 'Mal ở đây làm yêu cầu nhẹ hơn, không nhất thiết là một lần theo nghĩa đếm. Ngữ điệu vẫn quyết định mức lịch sự.','Trong “Du weißt das ja”, ja thường làm gì?','Gợi điều người nghe đã biết','Phủ định sự việc','Ja tình thái không phủ định nội dung.','Chỉ ngày mai','Ja không phải trạng từ thời gian.')
unit('Zweiteilige Konnektoren',43,'Liên từ đôi tạo tương quan: sowohl ... als auch; entweder ... oder; weder ... noch; nicht nur ... sondern auch; je ... desto. Hai vế nên song song về chức năng; không trộn các nửa của những cặp khác nhau.','Sie spricht sowohl Deutsch als auch Englisch.','Cô ấy nói cả tiếng Đức lẫn tiếng Anh.','Sowohl ... oder là ghép sai cặp. Je ... desto nối hai mức độ thay đổi, không dùng để thay und thông thường.','Sie spricht sowohl Deutsch ___ auch Englisch.','als','oder','Oder thuộc entweder ... oder, không thuộc sowohl.','noch','Noch thuộc weder ... noch, không thuộc sowohl.')
# All ambiguous fragments are explicitly scoped in the catalogue; no hidden guess of source hierarchy.
spec=json.loads(Path('scripts/grammar-authoring/requested-topics.json').read_text())
titles=list(dict.fromkeys(t for v in spec.values() for t in v.split('|')))
missing=[t for t in titles if t not in rows]
assert not missing,missing

def group(t):
 if t in ['Daher','Deshalb','Trotzdem','Jedoch','Nämlich','Konjunktionaladverbien','Konjunktionen','Seitdem oder seit dem']:return 'sentences'
 if 'Präposition' in t or 'adverb' in t.lower() or t in ['Uhrzeit im Deutschen','Am Mittag oder zu Mittag','Hinauf – herauf, hinunter – herunter, hinab – herab']:return 'relations'
 if any(x in t for x in ['Passiv','Partizip','Perfekt','Präteritum','Futur','Konjunktiv','Verb','Infinitiv','Imperativ','Indikativ']) or t in ['Hätte, wäre, würde','Nomen Verb Verbindungen','Nominalisierung','Gerundiv','Modalpartikel','Partikel']:return 'verbs'
 if any(x in t for x in ['satz','Satz','Konnektor','Konjunktion','dass','Dass','Frage','Rede','TEKAMOLO','Ohne dass','Dadurch dass']):return 'sentences'
 return 'words'
labels={'im Akkusativ':'Đại từ & danh ngữ ở Akkusativ','im Dativ':'Đại từ & danh ngữ ở Dativ','im Genitiv':'Danh ngữ ở Genitiv','mit bestimmtem Artikel':'Tính từ sau mạo từ xác định','mit unbestimmtem Artikel':'Tính từ sau mạo từ không xác định','mit Komparativ und Superlativ':'Biến cách dạng so sánh','mit was und wo':'Mệnh đề quan hệ với was/wo','ohne Artikel':'Tính từ khi không có mạo từ'}
advanced={
'Subjektive Bedeutung von Modalverben':('Nguồn tin nâng cao: sollen và wollen','**Sie soll die Prüfung bestanden haben** dẫn lời người khác; **sie will die Prüfung bestanden haben** thuật lại lời tự khẳng định của chính cô ấy. Phân biệt với **sie will die Prüfung bestehen** nêu ý định tương lai. Khi phủ định khả năng: **Sie kann nicht dort gewesen sein**, không dùng nicht müssen như một phủ định chắc chắn.', 'Sie soll die Prüfung bestanden haben.','Nghe nói cô ấy đã đỗ kỳ thi.','Sie soll die Prüfung bestanden ___.','haben','Bestehen với tân ngữ die Prüfung tạo Perfekt bằng haben; sollen ở đây dẫn tin chứ không diễn đạt nghĩa vụ.'),
'Akkusativ':('Akkusativ nâng cao: bổ ngữ, đo lường và bị động','Không phải Akkusativ nào cũng là tân ngữ chuyển thành chủ ngữ bị động. **Den ganzen Tag** có thể là trạng ngữ thời lượng; **einen Kilometer** có thể là khoảng cách. Với **jemanden eines Vergehens beschuldigen**, người bị buộc tội là Akkusativ còn hành vi là Genitiv. Dựa trên vai trò và rektion, không chỉ nhận diện đuôi.', 'Man beschuldigte ihn des Betrugs.','Người ta buộc tội anh ấy gian lận.','Man beschuldigte ___ des Betrugs. (er)','ihn','Beschuldigen có người ở Akkusativ (ihn) và hành vi ở Genitiv (des Betrugs). Ihm sẽ sai cách người bị buộc tội.'),
'Dativ':('Dativ nâng cao: giữ cách khi đổi cấu trúc','Ở bị động không chủ ngữ, Dativ không tự thành Nominativ: **Man hilft den Gästen → Den Gästen wird geholfen**. **Es** giữ chỗ chỉ đứng Vorfeld và mất khi một thành phần khác lên đầu. Ở hai đại từ không nhấn mạnh, Akkusativ thường trước Dativ: **Man gibt es ihm**.', 'Den Gästen wird geholfen.','Các vị khách được giúp đỡ.','Den Gästen ___ geholfen. (werden; Präsens)','wird','Den Gästen là Dativ, không phải chủ ngữ số nhiều. Câu không có chủ ngữ nên wird ngôi ba số ít, không phải werden.'),
'Futur 2':('Futur II nâng cao: phỏng đoán và hoàn tất','**Bis morgen wird sie angekommen sein** đặt giới hạn hoàn tất tương lai; **Sie wird inzwischen angekommen sein** thường là phỏng đoán về việc đã xảy ra. Thì hình thức không quyết định duy nhất thời gian thực. Trong mệnh đề phụ: **dass sie angekommen sein wird**; động từ chia ở cuối.', 'Ich vermute, dass sie inzwischen angekommen sein wird.','Tôi đoán rằng đến giờ cô ấy đã tới.','Ich vermute, dass sie angekommen sein ___. (werden)','wird','Trong mệnh đề phụ với Futur II thông thường, cụm angekommen sein đứng trước động từ hữu hạn wird.'),
'Gerundiv':('Gerundiv nâng cao: rút gọn nhưng giữ nghĩa','**Die bis Freitag einzureichenden Unterlagen** tương ứng giấy tờ phải nộp trước thứ Sáu. Cần kiểm tra phạm vi nghĩa vụ/khả năng từ ngữ cảnh và giữ đuôi định ngữ. Với tiền tố tách, zu chèn giữa: einzureichend. Không nhầm **einreichende Personen** (người nộp) với **einzureichende Unterlagen** (giấy cần nộp).','Die bis Freitag einzureichenden Unterlagen sind vollständig.','Các giấy tờ cần nộp trước thứ Sáu đã đầy đủ.','Die bis Freitag ___ Unterlagen sind vollständig. (einreichen; Gerundiv)','einzureichenden','Einzureichend là zu + Partizip I của động từ tách einreichen; sau die số nhiều cần -en.'),
'Indirekte Rede':('Lời gián tiếp nâng cao: nguồn tin và điểm nhìn','Giữ khoảng cách nguồn tin mà không tự quy lời người khác là sai. Với **Sie sagten: Wir kommen morgen**, có thể thuật **Sie sagten, sie kämen am folgenden Tag** nếu đổi điểm nhìn ngày và cần dạng thay thế vì sie kommen trùng Indikativ. Không đổi morgen thành ngày sau nếu thời điểm thuật vẫn cùng ngày và nghĩa không yêu cầu.','Sie sagten, sie kämen am folgenden Tag.','Họ nói rằng họ sẽ đến vào ngày hôm sau.','Sie sagten, sie ___ am folgenden Tag. (kommen; KII thay thế)','kämen','Sie kommen trùng Indikativ; kämen có thể dùng làm Konjunktiv II thay thế trong lời gián tiếp, không tự mang nghĩa quá khứ.'),
'Konjunktiv 1':('Konjunktiv I nâng cao: dạng trùng và thay thế','**Er sagt, er habe Zeit** đánh dấu rõ nguồn lời; **sie sagen, sie haben Zeit** không phân biệt hình thức với Indikativ. Khi cần làm rõ, dùng **sie hätten Zeit** hoặc dạng würde phù hợp. Dạng thay thế không tự phủ nhận nội dung và không chuyển sự việc sang quá khứ.','Sie erklären, sie hätten keine Einwände.','Họ giải thích rằng họ không có ý kiến phản đối.','Sie erklären, sie ___ keine Einwände. (haben; KII thay thế)','hätten','Hätten là dạng thay thế cho Konjunktiv I số nhiều trùng Indikativ; trong câu này không tự có nghĩa đã có ở quá khứ.'),
'Konjunktiv 1 der Vergangenheit':('Quá khứ gián tiếp nâng cao: bị động','Perfekt bị động trong Konjunktiv I: **Der Antrag sei geprüft worden**. Không dùng geworden vì đó là werden nghĩa trở thành. Giữ Partizip và nguồn lời: **Die Behörde erklärte, der Antrag sei geprüft worden** không khẳng định người thuật đã tự kiểm chứng.','Die Behörde erklärte, der Antrag sei geprüft worden.','Cơ quan giải thích rằng đơn đã được kiểm tra.','Der Antrag sei geprüft ___. (Perfekt bị động)','worden','Konjunktiv I Perfekt bị động dùng sei + geprüft + worden; geworden thuộc nghĩa trở thành.'),
'N-Deklination':('Danh từ yếu nâng cao: nhóm hỗn hợp','Phân biệt nhóm yếu **des Studenten** với nhóm hỗn hợp **des Namens, des Gedankens, des Herzens**. Herz giống trung nhưng có dạng đặc biệt: das Herz, dem Herzen, des Herzens; không lấy một bảng giống đực để áp mọi trường hợp. Khi danh ngữ dài, kiểm tra từng thành phần thay vì chỉ mạo từ.','Die Bedeutung dieses Namens ist unklar.','Ý nghĩa của tên này chưa rõ.','Die Bedeutung dieses ___ ist unklar. (Name)','Namens','Name thuộc nhóm hỗn hợp, Genitiv số ít là Namens; không chỉ Name hoặc Namen.'),
'Nomen Verb Verbindungen':('Cụm chức năng nâng cao: thay đổi vai trò và thể','**Zur Sprache bringen** đưa vấn đề ra bàn; **zur Sprache kommen** vấn đề được đề cập. **Zur Verfügung stellen** cung cấp; **zur Verfügung stehen** có sẵn. Chuyển động từ chức năng có thể đổi tác thể hoặc quá trình/trạng thái; không thay chúng chỉ để tránh lặp từ.','Das Problem kam erst später zur Sprache.','Mãi về sau vấn đề mới được đề cập.','Das Problem ___ zur Sprache. (kommen; Präteritum)','kam','Vấn đề làm chủ ngữ nên zur Sprache kommen; kam là Präteritum số ít, không phải brachte thiếu người đưa vấn đề ra.'),
'Nominalisierte Adjektive':('Tính từ danh từ hóa nâng cao: cách, số và nghĩa','**Mit den Beschäftigten**: Dativ số nhiều, đuôi yếu -en; **mit Beschäftigten** cũng có -en nhưng không từ đó suy mọi ô giống nhau. **Ein Deutscher / der Deutsche / mit einem Deutschen** thay đổi theo từ trước và cách. **Die Deutschen** chỉ người, còn **das Deutsche** có nghĩa khác theo ngữ cảnh.','Ich sprach mit einem Deutschen über die Reise.','Tôi đã nói chuyện với một người Đức về chuyến đi.','Ich sprach mit einem ___. (Deutscher)','Deutschen','Mit + Dativ và einem đã có tín hiệu cách nên tính từ danh từ hóa nhận -en; vẫn viết hoa.'),
'Nominalisierung':('Danh từ hóa nâng cao: giữ tác thể và đối tượng','**Die Prüfung des Antrags durch die Behörde** giữ đơn là đối tượng và cơ quan là người thực hiện. Genitiv có thể mơ hồ: **die Kritik des Ministers** có thể là lời phê bình từ bộ trưởng hoặc nhắm vào bộ trưởng; cần diễn đạt rõ bằng an/durch/từ vựng thích hợp. Không nén thông tin đến mức mất quan hệ.','Die Prüfung des Antrags durch die Behörde dauert an.','Việc cơ quan xem xét đơn vẫn đang tiếp diễn.','Die Prüfung des ___ dauert an. (Antrag)','Antrags','Antrag giống đực, Genitiv số ít có -s: des Antrags. Đừng bỏ đuôi khi danh ngữ dài.'),
'Partizip 1':('Phân từ nâng cao: định ngữ mở rộng','**Die seit Stunden vor dem Gebäude wartenden Menschen** giữ mọi bổ ngữ trước Partizip I và toàn cụm trước danh từ. Có thể chuyển thành mệnh đề quan hệ cho dễ đọc. Partizip I thường chỉ hoạt động tương đối đồng thời với câu chính, không bắt buộc hiện tại tuyệt đối.','Die seit Stunden wartenden Menschen wurden unruhig.','Những người đã đợi nhiều giờ trở nên bồn chồn.','Die seit Stunden ___ Menschen wurden unruhig. (warten; Partizip I)','wartenden','Wartend + đuôi -en sau die số nhiều. Động từ chính quá khứ không bắt Partizip I thành Partizip II.'),
'Passiv Ersatzformen':('Thay bị động nâng cao: không đánh đồng nghĩa','**Die Datei lässt sich öffnen / ist zu öffnen / ist lesbar** không luôn đồng nghĩa. Lässt sich nhấn khả năng; ist zu mở khả năng/nghĩa vụ theo ngữ cảnh; -bar thường khả năng. **Die Tür gehört repariert** có sắc thái vùng/khẩu ngữ, không thay mẫu trung hòa trong mọi văn bản.','Die Vorschrift ist unbedingt zu beachten.','Quy định này nhất thiết phải được tuân thủ.','Die Vorschrift ist unbedingt zu ___. (beachten)','beachten','Sein + zu + Infinitiv ở đây nhấn nghĩa vụ, đặc biệt với unbedingt; cần nguyên mẫu beachten, không phải beachtet.'),
'Perfekt mit Modalverben':('Ersatzinfinitiv nâng cao trong mệnh đề phụ','Với Modalverb + động từ khác, Perfekt dùng cụm nguyên mẫu kép và trợ động từ đứng trước cụm ở mệnh đề phụ: **weil er hat arbeiten müssen**. Không đưa hat xuống cuối như quy tắc mệnh đề phụ thông thường. Phân biệt **weil er das nicht gewollt hat** khi không có nguyên mẫu bổ sung.','Er ist müde, weil er hat arbeiten müssen.','Anh ấy mệt vì đã phải làm việc.','Er ist müde, weil er ___ arbeiten müssen. (haben)','hat','Trợ động từ hữu hạn hat đứng trước cụm nguyên mẫu kép arbeiten müssen trong mẫu chuẩn này.'),
'Plusquamperfekt':('Plusquamperfekt nâng cao: tầng thời gian và bị động','**Der Antrag war geprüft worden, bevor die Sitzung begann** đặt việc kiểm tra trước cuộc họp. Phân biệt **war geprüft** trạng thái với **war geprüft worden** quá trình đã hoàn tất trước mốc. Không dùng Plusquamperfekt chỉ để làm câu trang trọng hơn nếu không có quan hệ thời gian cần nêu.','Der Antrag war geprüft worden, bevor die Sitzung begann.','Đơn đã được kiểm tra trước khi cuộc họp bắt đầu.','Der Antrag war geprüft ___, bevor die Sitzung begann.','worden','War + geprüft + worden tạo Plusquamperfekt bị động quá trình; geworden sẽ sai chức năng werden ở đây.'),
'Präpositionen mit Genitiv':('Giới từ Genitiv nâng cao trong lập luận','Học **mangels ausreichender Beweise**, **anhand der Unterlagen**, **zwecks einer Prüfung**, **seitens der Leitung** theo cả nghĩa và cách. Mangels chỉ thiếu điều kiện, zwecks chỉ mục đích, seitens chỉ phía tác thể. Với danh từ trần số nhiều có biến thể hình thái; ưu tiên mẫu rõ thay vì ép mọi trường hợp vào một bảng.','Mangels ausreichender Beweise wurde das Verfahren eingestellt.','Vụ việc bị đình chỉ do không đủ chứng cứ.','___ ausreichender Beweise wurde das Verfahren eingestellt. (do thiếu)','Mangels','Mangels diễn đạt thiếu chứng cứ; zwecks sẽ nói mục đích, seitens sẽ nói phía một chủ thể.'),
'Pronomen es':('Es nâng cao: đối chiếu chức năng trước khi lược','**Es wird getanzt → Heute wird getanzt**: es chỉ giữ chỗ. **Es regnet → Heute regnet es**: es chủ ngữ hình thức vẫn còn. **Es freut mich, dass du kommst** dùng es tương quan với mệnh đề; khả năng bỏ phụ thuộc kết cấu, không áp quy tắc bỏ tất cả es khi có từ đầu câu.','Heute wird im Saal getanzt.','Hôm nay có khiêu vũ trong hội trường.','Heute ___ im Saal getanzt. (werden; Präsens)','wird','Bị động không chủ ngữ dùng wird số ít; es giữ chỗ mất vì Heute đã đứng Vorfeld. Không thêm es ở Mittelfeld.')
}

items=[]
for title in titles:
 r=rows[title]; levels=[k for k,v in spec.items() if title in v.split('|')]; ident='elio-grammar-'+hashlib.sha256(title.encode()).hexdigest()[:16]
 # Original prose and examples above; extended guides are Elio's existing authored content.
 guide=book[r['guide']]
 content=f"## {title}\n### Quy tắc & cách dùng\n{r['rule']}\n\n### Ví dụ Đức–Việt\n> **{r['de']}**\n> → {r['vi']}\n\n### Lỗi · Bẫy, nguyên nhân & cách tránh\n{r['trap']}\n\n### Thực hành có phân tích\nBài tập bên dưới kiểm tra đúng cấu trúc này. Sau khi trả lời, đọc lý do của từng lựa chọn; câu dựng lại yêu cầu đúng câu mẫu đã cho và toàn bộ từ gợi ý. Các cách diễn đạt khác có thể hợp ngữ pháp nhưng không thuộc đáp án của dạng tái tạo này."
 exercises=[dict(type='fill',question=r['question'],answers=[r['answer']],explanation=r['rule']+' '+r['trap']),dict(type='quiz',question=r['question'],options=[r['bad1'],r['answer'],r['bad2']],answers=[r['answer']],explanation=f"Đúng: {r['answer']}. {r['rule']}\nKhông chọn {r['bad1']}: {r['why1']}\nKhông chọn {r['bad2']}: {r['why2']}"),dict(type='build',question='Tái tạo đúng câu mẫu đã học: '+r['vi'],tokens=list(reversed(r['de'].split())),answers=[r['de']],explanation='Câu mẫu: '+r['de']+' → '+r['vi']+' '+r['trap'])]
 if title in advanced:
  heading,theory,exde,exvi,question,answer,why=advanced[title]
  content+='\n\n### C1 · Cấu trúc nâng cao · '+heading+'\n'+theory+'\n\n**'+exde+'** → '+exvi
  exercises.append(dict(type='fill',question='C1 · '+question,answers=[answer],explanation=why))
 for e in exercises:e.update(origin='authored',answerSource='authored')
 items.append(dict(id=ident,collectionId='elio-grammar-atlas-v1',title=title,subtitle=labels.get(title,''),levels=levels,level=levels[0],group=group(title),content=content,exercises=exercises,atlasGuide=dict(title=guide['title'],content=guide['content']),origin='elio-authored',reviewSources=[{'title':'IDS grammis','url':'https://grammis.ids-mannheim.de/'},{'title':'Goethe: Deutsche Grammatik','url':'https://www.goethe.de/ins/de/de/prf/grm.html'}]))
guides={str(r['guide']):{k:book[r['guide']][k] for k in ['title','content']} for r in rows.values()}
for item in items:
 item['atlasGuideKey']=str(rows[item['title']]['guide']);del item['atlasGuide']
Path('public/js/grammar-atlas-data.js').write_text("'use strict';\nconst ElioGrammarAtlasGuides="+json.dumps(guides,ensure_ascii=False,separators=(',',':'))+';\nconst ElioGrammarAtlasData='+json.dumps(items,ensure_ascii=False,indent=1)+';\nfor(const lesson of ElioGrammarAtlasData)lesson.atlasGuide=ElioGrammarAtlasGuides[lesson.atlasGuideKey];\n')
print('topics',len(items),'level entries',sum(len(x['levels']) for x in items),'exercises',sum(len(x['exercises']) for x in items))
